/* 자동 생성 — tools/build_data.py. 직접 고치지 마세요. */
(window.TS_DATA = window.TS_DATA || {}).p1 = [{"id":"p1-001","level":1,"type":"1인 동작","scene":"사무실 로비에서 한 남자가 물뿌리개로 큰 화분에 물을 주고 있다. 뒤쪽에 유리창이 있다.","statements":["He's planting some flowers.","He's watering some plants.","He's washing a window.","He's drinking a glass of water."],"answer":1,"explanation":"정답 (B): '그가 식물에 물을 주고 있다.' (A)는 plant를 '심다'라는 동사로 바꾼 함정, (C)는 사진 속 창문을 이용했지만 닦는 동작은 없다. (D)는 water라는 같은 단어를 다른 의미(마실 물)로 쓴 함정이다.","part":1},{"id":"p1-002","level":1,"type":"1인 동작","scene":"카페 야외 테이블에 한 여성이 혼자 앉아 신문을 펼쳐 읽고 있다. 테이블 위에는 커피잔이 놓여 있다.","statements":["She's pouring some coffee.","She's folding a napkin.","She's ordering a meal.","She's reading a newspaper."],"answer":3,"explanation":"정답 (D): '그녀가 신문을 읽고 있다.' (A)는 커피잔이 보이지만 따르는 동작은 없다. (B)의 냅킨은 사진에 없고, (C)는 카페에서 연상되는 동작일 뿐 주문하고 있지 않다.","part":1},{"id":"p1-003","level":1,"type":"1인 동작","scene":"한 남자가 두 팔로 종이 상자 하나를 들고 계단을 올라가고 있다.","statements":["He's opening a box.","He's climbing a ladder.","He's carrying a box.","He's packing some boxes."],"answer":2,"explanation":"정답 (C): '그가 상자를 나르고 있다.' (A)는 상자는 맞지만 동작(여는 중)이 틀렸다. (B)는 climbing은 비슷하지만 계단이 아니라 사다리라고 해서 틀렸고, (D)는 상자에 물건을 넣는 동작이 아니다.","part":1},{"id":"p1-004","level":1,"type":"1인 동작","scene":"한 여성이 사무실 창가에 서서 휴대 전화로 통화를 하고 있다. 다른 손에는 서류철을 들고 있다.","statements":["She's talking on the phone.","She's opening the window.","She's writing a note.","She's hanging up a picture."],"answer":0,"explanation":"정답 (A): '그녀가 전화 통화를 하고 있다.' (B)는 창문이 보이지만 여는 동작이 없고, (C)는 메모를 쓰고 있지 않다. (D)는 사진에 없는 그림을 언급했다.","part":1},{"id":"p1-005","level":1,"type":"1인 동작","scene":"헬멧을 쓴 남자가 도로 가장자리를 따라 자전거를 타고 가고 있다.","statements":["He's riding a bicycle.","He's repairing a bicycle.","He's parking a car.","He's walking along the street."],"answer":0,"explanation":"정답 (A): '그가 자전거를 타고 있다.' (B)는 자전거는 맞지만 수리하는 동작이 아니다. (C)의 자동차는 사진에 없고, (D)는 걷고 있다고 해서 동작이 틀렸다.","part":1},{"id":"p1-006","level":1,"type":"1인 동작","scene":"주방에서 앞치마를 두른 남자가 도마 위에서 칼로 채소를 썰고 있다.","statements":["A man is washing some dishes.","A man is slicing some vegetables.","A man is setting a table.","A man is stirring a pot."],"answer":1,"explanation":"정답 (B): '남자가 채소를 썰고 있다.' (A), (C), (D) 모두 주방에서 연상되는 동작(설거지, 식탁 차리기, 냄비 젓기)이지만 사진 속 동작과 다르다.","part":1},{"id":"p1-007","level":2,"type":"2인 이상 동작","scene":"회사 로비에서 정장을 입은 남녀 두 사람이 마주 서서 악수를 하고 있다. 뒤쪽에 안내 데스크가 있다.","statements":["They're exchanging business cards.","They're waiting in line.","They're shaking hands.","They're sitting at a reception desk."],"answer":2,"explanation":"정답 (C): '그들이 악수를 하고 있다.' (A)는 비즈니스 인사에서 연상되는 명함 교환으로, 사진에는 명함이 없다. (B)는 줄을 서 있지 않고, (D)는 안내 데스크가 보이지만 두 사람은 서 있다.","part":1},{"id":"p1-008","level":2,"type":"1인 동작","scene":"한 남자가 복사기 덮개를 열고 유리판 위에 종이 한 장을 올려놓고 있다.","statements":["He's repairing a copy machine.","He's placing a sheet of paper on a copier.","He's stacking some coffee cups.","He's handing out some copies."],"answer":1,"explanation":"정답 (B): '그가 복사기 위에 종이 한 장을 놓고 있다.' (A)는 복사기는 맞지만 수리하는 동작이 아니다. (C)는 copy와 발음이 비슷한 coffee를 이용한 함정이고, (D)는 복사물을 나눠 주는 장면이 아니다.","part":1},{"id":"p1-009","level":2,"type":"2인 이상 동작","scene":"회의실 테이블에 여러 사람이 앉아 있고, 한 여성이 서서 벽의 스크린을 손으로 가리키고 있다.","statements":["Some people are leaving the room.","A woman is turning off the projector.","A woman is pointing at a screen.","Some people are arranging chairs."],"answer":2,"explanation":"정답 (C): '여자가 스크린을 가리키고 있다.' (A)는 사람들이 앉아 있으므로 틀렸다. (B)는 회의실에서 연상되는 프로젝터 조작, (D)는 의자를 정리하는 동작으로 사진과 다르다.","part":1},{"id":"p1-010","level":2,"type":"2인 이상 동작","scene":"안전모를 쓴 작업자 두 명이 긴 나무 판자의 양쪽 끝을 하나씩 들고 함께 옮기고 있다.","statements":["They're putting on helmets.","They're painting a fence.","They're sawing some wood.","They're carrying a board together."],"answer":3,"explanation":"정답 (D): '그들이 판자를 함께 나르고 있다.' (A)는 이미 쓰고 있는 상태(wearing)를 쓰는 동작(putting on)으로 바꾼 대표 함정이다. (B)의 울타리는 없고, (C)는 나무는 맞지만 톱질하고 있지 않다.","part":1},{"id":"p1-011","level":2,"type":"1인 동작","scene":"옷 가게에서 한 여성이 재킷을 입은 채 전신 거울 앞에 서서 자신의 모습을 보고 있다. 옆에 옷걸이 행거가 있다.","statements":["She's hanging a jacket on a rack.","She's paying at a counter.","She's wiping a mirror.","She's looking in a mirror."],"answer":3,"explanation":"정답 (D): '그녀가 거울을 보고 있다.' (A)는 행거가 보이지만 재킷을 거는 동작이 아니다. (B)는 가게에서 연상되는 계산 장면이고, (C)는 거울은 맞지만 닦는 동작이 아니다.","part":1},{"id":"p1-012","level":2,"type":"2인 이상 동작","scene":"카페 계산대 앞에 손님 네 명이 한 줄로 서서 차례를 기다리고 있다. 아직 아무도 음료를 들고 있지 않다.","statements":["Some people are standing in line.","Some people are sitting at a counter.","A server is wiping the counter.","Some people are drinking coffee."],"answer":0,"explanation":"정답 (A): '사람들이 줄을 서 있다.' (B)는 counter는 맞지만 앉아 있지 않다. (C)는 계산대를 닦는 직원이 없고, (D)는 카페에서 연상되는 동작일 뿐 아무도 마시고 있지 않다.","part":1},{"id":"p1-013","level":3,"type":"상태(수동태 진행/완료)","scene":"사람이 없는 빈 회의실 구석 벽에 접이식 의자들이 여러 개 겹쳐 쌓여 있다.","statements":["Some chairs are being stacked.","Some people are sitting on chairs.","Some chairs have been stacked against a wall.","A table is being moved."],"answer":2,"explanation":"정답 (C): '의자들이 벽에 기대어 쌓여 있다.' (A)의 'is being + p.p.'는 지금 누군가 쌓고 있다는 뜻인데 사진에 사람이 없다. (B)는 사람이 없고, (D)도 옮기는 사람이 없으므로 진행 수동태가 될 수 없다.","part":1},{"id":"p1-014","level":3,"type":"사물·배경","scene":"도서관 서가의 선반마다 책이 빽빽하게 꽂혀 있다. 주변에 사람은 보이지 않는다.","statements":["Books are arranged on shelves.","Some books are being put on shelves.","A librarian is sorting books.","Some shelves are empty."],"answer":0,"explanation":"정답 (A): '책들이 선반에 정리되어 있다.' (B)는 사람이 없으므로 '꽂히고 있는 중'이라는 진행 수동태가 틀렸다. (C)의 사서는 사진에 없고, (D)는 선반이 가득 차 있으므로 틀렸다.","part":1},{"id":"p1-015","level":3,"type":"1인 동작","scene":"안경을 쓴 여성이 책상에 앉아 컴퓨터 모니터를 보고 있다. 책상 한쪽에 스탠드가 있다.","statements":["She's putting on her glasses.","She's wearing glasses.","She's cleaning a monitor.","She's adjusting a lamp."],"answer":1,"explanation":"정답 (B): '그녀가 안경을 쓰고 있다(착용 상태).' (A)의 putting on은 '쓰는 동작'이므로 이미 쓴 상태와 다르다. (C)는 모니터를 닦고 있지 않고, (D)는 스탠드를 조절하는 동작이 없다.","part":1},{"id":"p1-016","level":3,"type":"사물·배경","scene":"항구의 부두를 따라 작은 배 여러 척이 밧줄에 묶여 나란히 정박해 있다. 사람은 보이지 않는다.","statements":["Some boats are sailing on the open sea.","Some boats are docked in a harbor.","Some people are boarding a boat.","A bridge is being built over the water."],"answer":1,"explanation":"정답 (B): '배 몇 척이 항구에 정박해 있다.' (A)는 배는 맞지만 항해 중이 아니다. (C)는 사람이 없고, (D)는 사진에 없는 다리와 공사를 언급했다.","part":1},{"id":"p1-017","level":3,"type":"상태(수동태 진행/완료)","scene":"복도에서 한 남자가 대걸레로 바닥을 닦고 있고, 바닥에는 '미끄럼 주의' 표지판이 세워져 있다.","statements":["The floor has been covered with a rug.","A sign is being hung on the wall.","Some doors are being painted.","The floor is being mopped."],"answer":3,"explanation":"정답 (D): '바닥이 닦이고 있다.' 사람이 실제로 닦고 있으므로 진행 수동태가 맞다. (A)의 깔개는 없고, (B)는 표지판이 벽이 아니라 바닥에 세워져 있다. (C)는 문을 칠하는 사람이 없다.","part":1},{"id":"p1-018","level":3,"type":"2인 이상 동작","scene":"두 남자가 테이블 위에 넓게 펼쳐 놓은 건물 설계 도면을 함께 내려다보고 있다.","statements":["They're looking over some plans.","They're rolling up a poster.","They're drawing on a whiteboard.","One of the men is hanging a picture."],"answer":0,"explanation":"정답 (A): '그들이 도면을 살펴보고 있다.' (B)는 펼쳐진 종이를 말고 있다고 해서 동작이 틀렸다. (C)의 화이트보드와 (D)의 그림은 사진에 없다.","part":1},{"id":"p1-019","level":4,"type":"상태(수동태 진행/완료)","scene":"영업 전의 빈 식당. 테이블마다 접시, 유리잔, 접힌 냅킨이 가지런히 놓여 있고 사람은 없다.","statements":["Tables have been set for a meal.","Some dishes are being washed.","A waiter is setting the tables.","Food is being served."],"answer":0,"explanation":"정답 (A): '테이블이 식사를 위해 차려져 있다(완료 상태).' (B)와 (D)는 사람이 없는데 진행 수동태를 써서 틀렸다. (C)는 동사 set은 맞지만 차리는 웨이터가 사진에 없다.","part":1},{"id":"p1-020","level":4,"type":"1인 동작","scene":"건물 옆 도로변에 차 한 대가 서 있고 보닛이 열려 있다. 한 남자가 몸을 숙여 엔진을 들여다보고 있다.","statements":["A man is getting into a car.","A car is being towed.","Some tires are stacked by the building.","A man is leaning over a vehicle."],"answer":3,"explanation":"정답 (D): '남자가 차량 위로 몸을 숙이고 있다.' vehicle은 car를 바꿔 말한 표현이다. (A)는 차에 타는 동작이 아니고, (B)는 견인되는 장면이 아니다. (C)의 타이어 더미는 사진에 없다.","part":1},{"id":"p1-021","level":4,"type":"상태(수동태 진행/완료)","scene":"퇴근 후의 빈 사무실. 책상 위 스탠드가 켜져 있고, 의자는 책상 아래로 밀어 넣어져 있다. 책상 위는 깨끗하게 정리되어 있다.","statements":["A lamp is being installed.","Some papers are scattered on the floor.","A chair has been pushed under a desk.","A desk is being cleared."],"answer":2,"explanation":"정답 (C): '의자가 책상 아래로 밀어 넣어져 있다.' (A)와 (D)는 사람이 없는데 진행 수동태(is being)를 써서 틀렸다. (B)는 바닥에 흩어진 서류가 없다.","part":1},{"id":"p1-022","level":4,"type":"사물·배경","scene":"건물 입구 문 양쪽에 큰 화분이 하나씩 놓여 있고, 문 앞에 낮은 계단 세 칸이 있다. 사람은 없다.","statements":["Some plants are being watered.","Potted plants have been placed on both sides of an entrance.","A door is being closed.","Some flowers are being planted in the ground."],"answer":1,"explanation":"정답 (B): '입구 양쪽에 화분이 놓여 있다.' (A), (C), (D)는 모두 사람이 없는데 진행 수동태를 쓴 함정이다. 특히 (D)는 화분이 아니라 땅에 심는다고 해서 사물 위치도 틀렸다.","part":1},{"id":"p1-023","level":4,"type":"2인 이상 동작","scene":"안전모를 쓴 작업자 두 명 중 한 명은 사다리 위에서 천장 조명을 손보고 있고, 다른 한 명은 아래에서 사다리를 붙잡고 있다.","statements":["Both workers are climbing a ladder.","One of the workers is taking off his helmet.","They're folding up a ladder.","One of the workers is holding a ladder."],"answer":3,"explanation":"정답 (D): '작업자 중 한 명이 사다리를 붙잡고 있다.' (A)는 한 명만 사다리 위에 있으므로 Both가 틀렸다. (B)는 안전모를 쓰고 있는 상태를 벗는 동작으로 바꾼 함정이고, (C)는 사다리를 접고 있지 않다.","part":1},{"id":"p1-024","level":4,"type":"상태(수동태 진행/완료)","scene":"호텔 로비 한쪽에 여행 가방 여러 개가 실린 짐 카트가 서 있다. 주변에 사람은 없다.","statements":["A cart is being pushed across the lobby.","Some suitcases are being unpacked.","Some luggage has been loaded onto a cart.","Some travelers are checking in at the front desk."],"answer":2,"explanation":"정답 (C): '짐이 카트에 실려 있다(완료 상태).' (A)와 (B)는 사람이 없는데 진행 수동태를 썼다. (D)는 호텔에서 연상되는 장면이지만 사람이 보이지 않는다.","part":1},{"id":"p1-025","level":5,"type":"사물·배경","scene":"사람이 없는 회의실. 긴 테이블 주위에 의자들이 가지런히 놓여 있고, 테이블 가운데에 생수병들이 한 줄로 놓여 있다. 창문 블라인드는 반쯤 내려져 있다.","statements":["Some bottles have been lined up on a table.","Some blinds are being lowered.","Some chairs have been stacked in a corner.","Water is being poured into glasses."],"answer":0,"explanation":"정답 (A): '병들이 테이블 위에 한 줄로 놓여 있다.' (B)는 블라인드가 이미 내려진 상태인데 '내려지고 있는 중'이라고 해서 틀렸다. (C)는 의자가 테이블 주위에 있으므로 틀렸고, (D)는 사람도 유리잔도 없다.","part":1},{"id":"p1-026","level":5,"type":"사물·배경","scene":"공원 산책로를 따라 가로등이 일정한 간격으로 서 있다. 길옆 나무 그늘 아래 벤치들은 비어 있다.","statements":["Some benches are occupied.","A path is lined with lampposts.","Some trees are being trimmed.","Some leaves are being swept off the path."],"answer":1,"explanation":"정답 (B): '길을 따라 가로등이 늘어서 있다.' (A)는 벤치가 비어 있으므로 틀렸다(occupied = 사람이 차지한). (C)와 (D)는 작업하는 사람이 없는데 진행 수동태를 썼다.","part":1},{"id":"p1-027","level":5,"type":"상태(수동태 진행/완료)","scene":"한 남자가 건물 외벽에 사다리를 기대어 세워 두고, 그 옆 바닥에 쪼그려 앉아 페인트 통 뚜껑을 열고 있다. 벽은 아직 칠해지지 않았다.","statements":["A wall is being painted.","A ladder is leaning against a wall.","A man is climbing a ladder.","Some paint has been spilled on the ground."],"answer":1,"explanation":"정답 (B): '사다리가 벽에 기대어 있다.' (A)는 페인트 통을 보고 떠올리기 쉽지만 아직 칠하는 중이 아니다. (C)는 남자가 바닥에 앉아 있으므로 틀렸고, (D)는 페인트가 쏟아진 흔적이 없다.","part":1},{"id":"p1-028","level":5,"type":"상태(수동태 진행/완료)","scene":"부두의 화물선 옆에 컨테이너들이 여러 층으로 쌓여 있고, 대형 크레인 한 대가 움직이지 않고 서 있다. 사람은 보이지 않는다.","statements":["A crane is lifting a container.","Some cargo is being unloaded from a ship.","Containers have been stacked on a dock.","Some workers are directing traffic."],"answer":2,"explanation":"정답 (C): '컨테이너들이 부두에 쌓여 있다.' (A)는 크레인이 멈춰 있으므로 틀렸고, (B)는 하역 작업이 진행 중이 아니다. (D)는 사람이 보이지 않는다.","part":1},{"id":"p1-029","level":5,"type":"2인 이상 동작","scene":"서점에서 한 여성이 책장에서 책 한 권을 꺼내고 있고, 그 옆의 남자는 다른 책을 펼쳐 읽고 있다.","statements":["One of the people is removing a book from a shelf.","They're both reading the same book.","A man is putting a book back on a shelf.","A woman is paying for some books."],"answer":0,"explanation":"정답 (A): '한 사람이 선반에서 책을 꺼내고 있다.' (B)는 두 사람이 각자 다른 일을 하므로 틀렸다. (C)는 동작 방향이 반대(꺼내기 ↔ 다시 꽂기)이고 주어도 틀렸으며, (D)는 계산하는 장면이 없다.","part":1},{"id":"p1-030","level":5,"type":"사물·배경","scene":"창가 사무실 책상 위에 모니터 두 대가 나란히 켜져 있고, 키보드 옆 전화기의 수화기는 제자리에 놓여 있다. 창밖으로 고층 건물들이 보인다.","statements":["A telephone receiver has been left off the hook.","Some windows are being cleaned.","A computer is being set up.","Two monitors have been positioned side by side."],"answer":3,"explanation":"정답 (D): '모니터 두 대가 나란히 놓여 있다.' (A)는 수화기가 제자리에 있으므로 틀렸다(off the hook = 내려져 있는). (B)와 (C)는 사람이 없는데 진행 수동태를 쓴 함정이다.","part":1},{"id":"p1-031","level":1,"type":"1인 동작","scene":"공사 현장에서 안전모를 쓴 남자가 흙이 담긴 외바퀴 손수레를 밀고 있다. 뒤쪽에 벽돌 더미가 있다.","statements":["He's taking off his helmet.","He's pushing a wheelbarrow.","He's climbing a ladder.","He's painting a wall."],"answer":1,"explanation":"정답 (B): '그가 외바퀴 손수레를 밀고 있다.' (A)는 안전모를 쓰고 있을 뿐 벗는 동작이 아니다. (C)의 사다리는 사진에 없고, (D)는 벽을 칠하는 동작이 없다.","part":1},{"id":"p1-032","level":1,"type":"1인 동작","scene":"슈퍼마켓 과일 코너에서 장바구니를 팔에 건 여자가 진열대의 사과를 집어 들고 있다.","statements":["She's paying at the counter.","She's picking up some fruit.","She's pushing a shopping cart.","She's peeling an apple."],"answer":1,"explanation":"정답 (B): '그녀가 과일을 집어 들고 있다.' (A)는 계산대에서 계산하는 장면이 아니고, (C)는 장바구니를 들고 있을 뿐 카트는 없다. (D)는 사과(apple)를 이용했지만 껍질을 벗기는 동작이 아니다.","part":1},{"id":"p1-033","level":1,"type":"1인 동작","scene":"도서관에서 한 남자가 손에 든 책을 서가 빈자리에 꽂고 있다.","statements":["He's reading a magazine.","He's building some shelves.","He's putting a book on a shelf.","He's writing in a notebook."],"answer":2,"explanation":"정답 (C): '그가 책을 선반에 꽂고 있다.' (A)는 잡지를 읽고 있지 않고, (B)는 shelf를 이용했지만 선반을 만드는 동작이 아니다. (D)는 공책에 쓰는 동작이 없다.","part":1},{"id":"p1-034","level":1,"type":"2인 이상 동작","scene":"공원 벤치에 두 사람이 나란히 앉아 서로 이야기를 나누고 있다. 뒤로 나무들이 보인다.","statements":["They're sitting on a bench.","They're jogging in the park.","They're painting a bench.","They're feeding some birds."],"answer":0,"explanation":"정답 (A): '그들이 벤치에 앉아 있다.' (B)는 공원에서 연상되는 동작이지만 달리고 있지 않다. (C)는 bench를 반복했지만 칠하는 동작이 아니고, (D)의 새는 사진에 없다.","part":1},{"id":"p1-035","level":1,"type":"2인 이상 동작","scene":"실험실에서 흰 가운을 입은 두 사람이 실험대 앞에 서서 한 사람은 현미경을 들여다보고, 다른 사람은 옆에서 지켜보고 있다.","statements":["They're wearing lab coats.","They're washing some glasses.","They're taking off their gloves.","They're leaving the laboratory."],"answer":0,"explanation":"정답 (A): '그들이 실험실 가운을 입고 있다.' (B)는 유리 기구를 씻는 동작이 없고, (C)는 입고 있는 상태(wearing)와 벗는 동작(taking off)을 혼동시키는 함정이다. (D)는 실험실을 나가고 있지 않다.","part":1},{"id":"p1-036","level":1,"type":"사물·배경","scene":"기차역 승강장에 열차 한 대가 멈춰 서 있다. 승강장에는 사람이 없다.","statements":["Passengers are boarding a train.","A train is going through a tunnel.","A train is stopped at a platform.","Some tracks are being repaired."],"answer":2,"explanation":"정답 (C): '열차가 승강장에 멈춰 있다.' (A)는 사람이 없으므로 탑승하는 승객도 없다. (B)의 터널은 사진에 없고, (D)는 선로를 고치는 사람이 없다.","part":1},{"id":"p1-037","level":1,"type":"사물·배경","scene":"건물 앞 자전거 거치대에 자전거 여러 대가 나란히 세워져 있다. 주변에 사람은 없다.","statements":["Some people are riding bicycles.","A bicycle is being repaired.","Some cars are parked on the street.","Some bicycles are parked in a rack."],"answer":3,"explanation":"정답 (D): '자전거들이 거치대에 세워져 있다.' (A)와 (B)는 사람이 없으므로 타거나 고치는 동작이 있을 수 없다. (C)는 parked를 반복했지만 자동차는 사진에 없다.","part":1},{"id":"p1-038","level":1,"type":"상태(수동태 진행/완료)","scene":"야외 카페의 테이블마다 파라솔이 펼쳐져 있다. 손님은 아무도 없다.","statements":["Some umbrellas are being closed.","Some people are eating outside.","Some tables are being cleaned.","Some umbrellas are open over the tables."],"answer":3,"explanation":"정답 (D): '테이블 위로 파라솔들이 펼쳐져 있다.' (A)는 사람이 없는데 '접히고 있는 중(being closed)'이라고 한 함정이다. (B)는 손님이 없고, (C)도 닦는 사람이 없다.","part":1},{"id":"p1-039","level":2,"type":"1인 동작","scene":"정원에서 한 여자가 무릎을 꿇고 모종삽으로 꽃을 심고 있다. 옆 잔디 위에 호스가 놓여 있다.","statements":["She's watering some flowers.","She's kneeling in a garden.","She's picking some flowers.","She's mowing the lawn."],"answer":1,"explanation":"정답 (B): '그녀가 정원에서 무릎을 꿇고 있다.' (A)는 호스가 보이지만 물을 주는 동작은 없다. (C)는 꽃을 꺾는 동작이 아니고, (D)는 잔디(lawn)에서 연상되는 동작이지만 잔디를 깎고 있지 않다.","part":1},{"id":"p1-040","level":2,"type":"1인 동작","scene":"창고 안에서 한 남자가 지게차를 운전하며 상자가 실린 팔레트를 옮기고 있다.","statements":["He's lifting a box by hand.","He's sweeping the floor.","He's getting out of a vehicle.","He's operating a forklift."],"answer":3,"explanation":"정답 (D): '그가 지게차를 조종하고 있다.' (A)는 상자를 옮기는 것은 맞지만 손으로 드는 것이 아니다. (B)는 바닥을 쓸고 있지 않고, (C)는 차량에서 내리는 중이 아니라 타고 있다.","part":1},{"id":"p1-041","level":2,"type":"1인 동작","scene":"작업장에서 보안경을 쓴 남자가 전동 드릴로 나무판에 구멍을 뚫고 있다.","statements":["He's drilling a hole in a board.","He's putting on safety glasses.","He's cutting down a tree.","He's hammering a nail."],"answer":0,"explanation":"정답 (A): '그가 판자에 구멍을 뚫고 있다.' (B)는 이미 쓰고 있는 상태를 '쓰는 중(putting on)'이라고 한 대표 함정이다. (C)는 나무(wood)에서 연상되는 tree를 이용했고, (D)의 망치는 사진에 없다.","part":1},{"id":"p1-042","level":2,"type":"2인 이상 동작","scene":"미용실에서 미용사가 의자에 앉은 손님의 머리카락을 가위로 자르고 있다. 앞에 큰 거울이 있다.","statements":["A customer is washing her hair.","A customer is paying for a haircut.","They're sweeping hair off the floor.","A stylist is cutting a customer's hair."],"answer":3,"explanation":"정답 (D): '미용사가 손님의 머리를 자르고 있다.' (A)는 머리를 감는 장면이 아니고, (B)는 haircut을 이용했지만 계산하는 동작은 없다. (C)는 hair를 반복했을 뿐 바닥을 쓸고 있지 않다.","part":1},{"id":"p1-043","level":2,"type":"2인 이상 동작","scene":"부두에서 두 남자가 밧줄을 당겨 작은 배를 말뚝에 묶고 있다.","statements":["They're tying a boat to a dock.","They're swimming in the water.","They're rowing a boat.","They're fishing off a pier."],"answer":0,"explanation":"정답 (A): '그들이 배를 부두에 묶고 있다.' (B)는 물에서 연상되는 동작일 뿐이고, (C)는 boat를 반복했지만 노를 젓고 있지 않다. (D)는 부두에서 연상되는 낚시지만 그런 동작은 없다.","part":1},{"id":"p1-044","level":2,"type":"사물·배경","scene":"미술관 전시실 벽에 그림 여러 점이 걸려 있고, 방 가운데에 긴 벤치가 하나 있다. 관람객은 없다.","statements":["Some visitors are looking at the artwork.","Some paintings are hanging on the wall.","A painting is being hung.","Some paintings are leaning against a bench."],"answer":1,"explanation":"정답 (B): '그림들이 벽에 걸려 있다.' (A)는 관람객이 없고, (C)는 사람이 없는데 '걸리는 중(being hung)'이라고 한 함정이다. (D)는 그림이 벤치에 기대어 있지 않다.","part":1},{"id":"p1-045","level":2,"type":"사물·배경","scene":"건물 바깥의 돌계단 양쪽에 금속 난간이 설치되어 있다. 계단에는 아무도 없다.","statements":["Someone is climbing the stairs.","The stairs are being swept.","A staircase has railings on both sides.","A railing is being installed."],"answer":2,"explanation":"정답 (C): '계단 양쪽에 난간이 있다.' (A)는 계단을 오르는 사람이 없고, (B)와 (D)는 사람이 없는데 '진행 중인 수동태(being p.p.)'를 쓴 함정이다.","part":1},{"id":"p1-046","level":2,"type":"상태(수동태 진행/완료)","scene":"구내식당이 영업을 마친 뒤 의자들이 모두 테이블 위에 거꾸로 올려져 있다. 사람은 없다.","statements":["Some chairs are being stacked.","Some people are sitting at the tables.","Some chairs have been placed on the tables.","The floor is covered with a rug."],"answer":2,"explanation":"정답 (C): '의자들이 테이블 위에 올려져 있다.' (A)는 사람이 없으므로 '쌓고 있는 중(being stacked)'이 될 수 없다. (B)는 앉아 있는 사람이 없고, (D)의 깔개(rug)는 사진에 없다.","part":1},{"id":"p1-047","level":3,"type":"1인 동작","scene":"실험실에서 보안경을 쓴 여자가 스포이트로 시험관에 액체를 떨어뜨리고 있다. 실험대 끝에 클립보드가 놓여 있다.","statements":["She's taking off her goggles.","She's filling a test tube with a dropper.","She's washing some glassware in a sink.","She's writing some notes on a clipboard."],"answer":1,"explanation":"정답 (B): '그녀가 스포이트로 시험관을 채우고 있다.' (A)는 보안경을 쓰고 있는 상태를 벗는 동작으로 바꾼 함정이다. (C)는 개수대에서 씻고 있지 않고, (D)는 사진 속 클립보드를 이용했지만 메모하는 동작은 없다.","part":1},{"id":"p1-048","level":3,"type":"1인 동작","scene":"슈퍼마켓 통로에서 앞치마를 두른 직원이 상자에서 통조림을 꺼내 선반에 채우고 있다. 통로에 다른 사람은 없다.","statements":["An employee is stocking some shelves.","An employee is scanning items at a register.","A shopper is pushing a cart down an aisle.","Some cans are being weighed on a scale."],"answer":0,"explanation":"정답 (A): '직원이 선반에 물건을 채우고 있다.' (B)는 슈퍼마켓에서 연상되는 계산 동작이지만 계산대는 없다. (C)는 쇼핑객과 카트가 없고, (D)는 cans를 이용했지만 저울로 무게를 재고 있지 않다.","part":1},{"id":"p1-049","level":3,"type":"2인 이상 동작","scene":"공사 현장 비계 위에서 두 인부가 모르타르를 바르며 벽돌을 쌓아 올리고 있다.","statements":["Some workers are taking down a scaffold.","They're unloading bricks from a truck.","They're pouring concrete into a mold.","Some workers are laying bricks."],"answer":3,"explanation":"정답 (D): '인부들이 벽돌을 쌓고 있다.' (A)는 비계 위에서 일할 뿐 비계를 해체하고 있지 않다. (B)는 bricks를 반복했지만 트럭은 없고, (C)는 공사 현장에서 연상되는 동작일 뿐이다.","part":1},{"id":"p1-050","level":3,"type":"2인 이상 동작","scene":"기차 승강장에서 여행 가방을 든 승객들이 열린 문을 통해 열차에 올라타고 있다.","statements":["Some passengers are waiting in a ticket line.","Some passengers are boarding a train.","A conductor is checking some tickets.","Some passengers are getting off a bus."],"answer":1,"explanation":"정답 (B): '승객들이 열차에 타고 있다.' (A)는 매표 줄이 없고, (C)는 역에서 연상되는 승무원이지만 사진에 없다. (D)는 열차가 아니라 버스이고 동작도 반대(내리는 중)다.","part":1},{"id":"p1-052","level":3,"type":"사물·배경","scene":"식당 주방 조리대 위쪽 벽 고리에 냄비와 프라이팬들이 걸려 있다. 주방에는 사람이 없다.","statements":["Some pots are being washed in a sink.","A chef is cooking at a stove.","Some pots are hanging above a counter.","Some pans are stacked in a cupboard."],"answer":2,"explanation":"정답 (C): '냄비들이 조리대 위에 걸려 있다.' (A)는 사람이 없는데 씻기는 중이라고 했고, (B)의 요리사는 사진에 없다. (D)는 pans를 이용했지만 찬장 안에 쌓여 있지 않고 벽에 걸려 있다.","part":1},{"id":"p1-053","level":3,"type":"상태(수동태 진행/완료)","scene":"창고 선반마다 종이 상자들이 가지런히 정리되어 있고, 지게차 한 대가 한쪽에 세워져 있다. 사람은 없다.","statements":["Boxes are being loaded onto a forklift.","A forklift is carrying a pallet.","Boxes have been arranged on some shelves.","Some shelves are being assembled."],"answer":2,"explanation":"정답 (C): '상자들이 선반에 정리되어 있다.' (A)와 (D)는 사람이 없는데 진행 중인 수동태(being p.p.)를 쓴 함정이다. (B)는 지게차가 세워져 있을 뿐 팔레트를 나르고 있지 않다.","part":1},{"id":"p1-054","level":3,"type":"상태(수동태 진행/완료)","scene":"정원 옆 수도꼭지에 초록색 호스가 둥글게 감겨 걸려 있다. 화단에는 꽃이 피어 있고 사람은 없다.","statements":["A hose is being used to water plants.","A fence is being put up.","Some flowers are being planted.","A hose has been coiled up near a garden."],"answer":3,"explanation":"정답 (D): '정원 근처에 호스가 감겨 있다.' (A)는 호스가 감겨 있을 뿐 사용 중이 아니다. (B)와 (C)는 사람이 없는데 '진행 중'이라고 한 함정이다.","part":1},{"id":"p1-055","level":4,"type":"1인 동작","scene":"자전거 수리점에서 한 남자가 거치대에 올린 자전거의 타이어에 공기 펌프로 바람을 넣고 있다.","statements":["He's riding a bicycle down a path.","He's removing a wheel from a car.","He's inflating a bicycle tire.","He's locking a bicycle to a rack."],"answer":2,"explanation":"정답 (C): '그가 자전거 타이어에 바람을 넣고 있다.' (A)는 bicycle을 반복했지만 타고 있지 않다. (B)는 tire에서 연상되는 wheel과 자동차를 이용한 함정이고, (D)는 거치대(rack)를 이용했지만 자물쇠를 채우는 동작이 아니다.","part":1},{"id":"p1-056","level":4,"type":"2인 이상 동작","scene":"병원 접수대에서 간호사가 카운터 너머로 환자에게 서류 한 장을 건네고 있다.","statements":["A patient is lying in a hospital bed.","A nurse is taking a patient's temperature.","They're shaking hands across a counter.","A nurse is handing a form to a patient."],"answer":3,"explanation":"정답 (D): '간호사가 환자에게 서류를 건네고 있다.' (A)는 병원에서 연상되는 장면이지만 환자는 서 있다. (B)는 간호사가 할 법한 동작이지만 사진과 다르고, (C)는 카운터 너머로 손을 내민 모습을 악수로 착각하게 하는 함정이다.","part":1},{"id":"p1-057","level":4,"type":"2인 이상 동작","scene":"야외 카페에서 웨이터가 두 손님이 앉은 테이블에 음식 접시를 내려놓고 있다. 테이블 위에 메뉴판은 덮여 있다.","statements":["The diners are paying the bill.","A server is setting down some plates.","The diners are studying a menu.","A server is clearing the table."],"answer":1,"explanation":"정답 (B): '종업원이 접시를 내려놓고 있다.' (A)는 계산하는 장면이 없고, (C)는 메뉴판이 덮여 있으므로 보고 있지 않다. (D)는 접시를 놓는 것과 반대로 치우는(clearing) 동작이라 틀렸다.","part":1},{"id":"p1-058","level":4,"type":"사물·배경","scene":"아무도 없는 회의실. 앞쪽 벽에 화이트보드가 고정되어 있고 그 위에 도표가 그려져 있다. 의자들은 테이블 아래에 밀어 넣어져 있다.","statements":["A presentation is being given.","Some chairs are stacked in a corner.","Some notes are being erased from a whiteboard.","A whiteboard is mounted on the wall."],"answer":3,"explanation":"정답 (D): '화이트보드가 벽에 고정되어 있다.' (A)는 사람이 없으므로 발표 중일 수 없다. (B)는 의자가 테이블 아래에 있지 구석에 쌓여 있지 않고, (C)는 사람이 없는데 being erased를 쓴 함정이다.","part":1},{"id":"p1-059","level":4,"type":"사물·배경","scene":"강 위에 놓인 돌다리 아래로 작은 유람선 한 척이 지나가고 있다.","statements":["A bridge is being constructed over a river.","A boat is tied to a post.","A boat is passing under a bridge.","Some people are diving off a bridge."],"answer":2,"explanation":"정답 (C): '배가 다리 밑을 지나가고 있다.' (A)는 다리가 이미 완성되어 있는데 '건설 중'이라고 했다. (B)는 배가 움직이고 있으므로 묶여 있지 않고, (D)는 다이빙하는 사람이 없다.","part":1},{"id":"p1-060","level":4,"type":"사물·배경","scene":"공원 광장 가운데 분수가 물을 뿜고 있고, 그 주위를 벤치들이 둥글게 둘러싸고 있다. 벤치에는 아무도 앉아 있지 않다.","statements":["Water is being drained from a fountain.","Some benches surround a fountain.","Some trees are being trimmed.","Some people are seated on the benches."],"answer":1,"explanation":"정답 (B): '벤치들이 분수를 둘러싸고 있다.' (A)는 분수가 물을 뿜는 중인데 '물을 빼는 중'이라고 했다. (C)는 나무를 다듬는 사람이 없고, (D)는 벤치가 비어 있으므로 틀렸다.","part":1},{"id":"p1-061","level":4,"type":"상태(수동태 진행/완료)","scene":"도로 공사 구간. 차선을 따라 주황색 원뿔형 표지들이 줄지어 세워져 있고, 굴착기 한 대가 작업 없이 멈춰 있다.","statements":["Some traffic cones have been set up along the road.","Some cones are being loaded onto a truck.","A machine is digging a hole.","The road has been closed with a gate."],"answer":0,"explanation":"정답 (A): '도로를 따라 원뿔형 표지들이 세워져 있다.' (B)는 사람이 없는데 '싣는 중'이라고 했고, (C)는 굴착기가 멈춰 있으므로 땅을 파고 있지 않다. (D)는 closed가 그럴듯하지만 차단문(gate)은 사진에 없다.","part":1},{"id":"p1-062","level":4,"type":"상태(수동태 진행/완료)","scene":"영업 전 미용실. 빈 의자들 앞 거울 아래 선반에 가위와 빗, 드라이어가 가지런히 놓여 있다.","statements":["Some tools have been laid out in front of the mirrors.","A stylist is trimming a customer's hair.","Some chairs are being moved into a row.","Some mirrors are being cleaned."],"answer":0,"explanation":"정답 (A): '거울 앞에 도구들이 놓여 있다.' (B)는 미용실에서 연상되는 동작이지만 사람이 없다. (C)와 (D)는 사람이 없는데 진행 중인 수동태를 쓴 함정이다.","part":1},{"id":"p1-063","level":5,"type":"1인 동작","scene":"미술관 전시실에서 한 남자가 접이식 사다리 위에 서서 천장 조명의 각도를 조정하고 있다. 벽에는 이미 그림들이 걸려 있다.","statements":["A man is hanging a painting on the wall.","A man is adjusting a light fixture.","A man is folding up a ladder.","A man is climbing down some stairs."],"answer":1,"explanation":"정답 (B): '남자가 조명 기구를 조정하고 있다.' (A)는 그림이 이미 걸려 있는 상태를 거는 동작으로 바꾼 함정이다. (C)는 ladder를 이용했지만 사다리 위에 서 있을 뿐 접고 있지 않고, (D)는 climbing과 사다리를 연결시킨 함정으로 계단은 없다.","part":1},{"id":"p1-064","level":5,"type":"2인 이상 동작","scene":"부두에 댄 배 위에 선 남자가 나무 상자를 부두에 서 있는 다른 남자에게 건네고 있다.","statements":["Both men are standing on the boat.","One man is passing a crate to another.","Some crates are being lifted by a crane.","The men are unloading a truck."],"answer":1,"explanation":"정답 (B): '한 남자가 다른 남자에게 상자를 건네고 있다.' (A)는 한 사람만 배 위에 있으므로 Both가 틀렸다. (C)는 crane이 crate와 발음이 비슷한 함정이자 사진에 없는 장비이고, (D)는 짐을 내리는 동작은 비슷하지만 트럭이 아니다.","part":1},{"id":"p1-065","level":5,"type":"2인 이상 동작","scene":"목공 작업장에서 여러 사람이 작업대 둘레에 서서, 한 사람이 사포로 나무판을 다듬는 시범을 지켜보고 있다. 일부만 마스크를 쓰고 있다.","statements":["Everyone is wearing a protective mask.","One of the men is sawing a board in half.","Some people are gathered around a workbench.","Some tools are being put away in a cabinet."],"answer":2,"explanation":"정답 (C): '사람들이 작업대 주위에 모여 있다.' (A)는 일부만 마스크를 썼으므로 Everyone이 틀렸다. (B)는 sanding(사포질)과 발음이 비슷한 sawing(톱질)으로 바꾼 함정이고, (D)는 도구를 정리하는 사람이 없다.","part":1},{"id":"p1-066","level":5,"type":"사물·배경","scene":"천장까지 닿는 창고 선반들 사이 통로 가운데에 지게차 한 대가 서 있다. 사람은 보이지 않는다.","statements":["A forklift is parked between two rows of shelving.","A forklift is lifting a pallet onto a shelf.","Some shelves are being emptied.","A worker is driving a forklift out of the building."],"answer":0,"explanation":"정답 (A): '지게차가 두 줄의 선반 사이에 세워져 있다.' (B)는 지게차가 움직이지 않으므로 틀렸다. (C)는 사람이 없는데 진행 중인 수동태를 썼고, (D)는 운전하는 사람이 없다.","part":1},{"id":"p1-067","level":5,"type":"사물·배경","scene":"아무도 없는 도서관 열람실. 긴 테이블마다 독서용 스탠드가 일정한 간격으로 놓여 있고 창으로 햇빛이 들어온다. 스탠드는 꺼져 있다.","statements":["Some books are being returned to a desk.","Some students are studying at the tables.","The lamps are being switched on.","Reading lamps line the length of the tables."],"answer":3,"explanation":"정답 (D): '독서등들이 테이블을 따라 줄지어 있다.' (A)와 (C)는 사람이 없는데 진행 중인 수동태를 쓴 함정이고, (C)는 스탠드가 꺼져 있다는 점에서도 틀렸다. (B)는 도서관에서 연상되는 장면이지만 학생이 없다.","part":1},{"id":"p1-068","level":5,"type":"상태(수동태 진행/완료)","scene":"사람이 없는 주방 조리대 위에 썰어 놓은 채소가 그릇 여러 개에 나뉘어 담겨 있고, 도마 위에 칼이 놓여 있다.","statements":["Some vegetables are being chopped on a board.","A knife is being sharpened.","Some bowls have been stacked in a sink.","Some vegetables have been chopped and put in bowls."],"answer":3,"explanation":"정답 (D): '채소들이 썰려서 그릇에 담겨 있다.' (A)는 같은 동사 chop을 썼지만 '썰리고 있는 중(being chopped)'이라 사람이 없는 사진과 맞지 않는다. (B)도 진행 중인 동작이라 틀렸고, (C)는 have been을 써서 그럴듯하지만 그릇은 개수대가 아니라 조리대 위에 있다.","part":1},{"id":"p1-069","level":5,"type":"상태(수동태 진행/완료)","scene":"호숫가 보트 대여소. 비수기라 작은 보트들이 선착장 위에 뒤집힌 채로 나란히 놓여 있다. 사람은 없다.","statements":["Some boats have been turned upside down on a dock.","Some boats are being rowed across a lake.","Some boats are being pulled out of the water.","Some boats are floating next to the dock."],"answer":0,"explanation":"정답 (A): '보트들이 선착장 위에 뒤집혀 놓여 있다.' (B)와 (C)는 사람이 없는데 진행 중인 수동태를 쓴 함정으로, 특히 (C)는 보트가 물 밖에 있는 결과만 보고 고르기 쉽다. (D)는 보트가 물 위가 아니라 선착장 위에 있으므로 틀렸다.","part":1},{"id":"p1-070","level":5,"type":"상태(수동태 진행/완료)","scene":"빈 병실. 침대 시트가 반듯하게 정리되어 있고, 침대 둘레의 커튼은 한쪽으로 걷혀 있다.","statements":["A bed is being made.","A patient is resting in a bed.","A curtain has been pulled to one side.","A curtain is being drawn around a bed."],"answer":2,"explanation":"정답 (C): '커튼이 한쪽으로 걷혀 있다.' (A)는 침대가 이미 정돈된 상태인데 '정돈되는 중'이라고 했고, (B)는 환자가 없다. (D)는 curtain을 반복했지만 커튼을 치는 중도 아니고 오히려 걷혀 있다.","part":1},{"id":"p1-071","level":1,"type":"1인 동작","scene":"공항 체크인 카운터 앞에서 한 여성이 여행 가방을 수하물 저울 위에 올려놓고 있다.","statements":["She's putting a suitcase on a scale.","She's opening a suitcase.","She's boarding an airplane.","She's reading a magazine."],"answer":0,"explanation":"정답 (A): '여행 가방을 저울 위에 올려놓고 있다.' (B)는 suitcase를 반복했지만 가방을 열고 있지 않다. (C)는 공항에서 연상되는 '탑승하다'를 쓴 함정이고, (D)는 사진에 잡지가 없다.","part":1},{"id":"p1-072","level":1,"type":"1인 동작","scene":"세차장에서 한 남자가 호스로 자동차에 물을 뿌리며 차를 씻고 있다.","statements":["He's driving a car.","He's changing a tire.","He's washing a car.","He's watering a lawn."],"answer":2,"explanation":"정답 (C): '차를 씻고 있다.' (A)는 car를 반복했지만 운전 중이 아니고, (B)는 자동차에서 연상되는 타이어 교체다. (D)는 호스·물에서 연상되는 '잔디에 물 주기'로 만든 함정이다.","part":1},{"id":"p1-073","level":1,"type":"1인 동작","scene":"제과점 주방에서 흰 모자를 쓴 제빵사가 오븐에서 빵이 담긴 쟁반을 꺼내고 있다.","statements":["He's eating some bread.","He's taking a tray out of an oven.","He's washing a tray.","He's closing a window."],"answer":1,"explanation":"정답 (B): '오븐에서 쟁반을 꺼내고 있다.' (A)는 빵을 먹고 있지 않고, (C)는 tray를 반복했지만 씻는 동작이 아니다. (D)는 사진에 없는 동작이다.","part":1},{"id":"p1-074","level":1,"type":"1인 동작","scene":"코인 세탁소에서 한 여자가 앞이 열린 세탁기 안에 옷을 넣고 있다.","statements":["She's folding some towels.","She's putting clothes into a washing machine.","She's ironing a shirt.","She's hanging clothes outside."],"answer":1,"explanation":"정답 (B): '세탁기에 옷을 넣고 있다.' (A), (C), (D)는 모두 세탁소에서 연상되는 동작(수건 개기, 다림질, 빨래 널기)이지만 사진 속 동작과 다르다.","part":1},{"id":"p1-075","level":1,"type":"2인 이상 동작","scene":"테니스 코트에서 두 사람이 네트를 사이에 두고 라켓으로 공을 치고 있다.","statements":["They're playing tennis.","They're sitting on a bench.","They're fixing a net.","They're watching a game on TV."],"answer":0,"explanation":"정답 (A): '테니스를 치고 있다.' (B)는 두 사람이 서서 움직이고 있으므로 틀리고, (C)는 net을 반복한 함정이다. (D)는 경기를 TV로 보고 있지 않다.","part":1},{"id":"p1-076","level":1,"type":"2인 이상 동작","scene":"요가 교실에서 여러 사람이 각자 매트 위에 서서 두 팔을 머리 위로 뻗고 있다.","statements":["They're rolling up their mats.","They're running on a track.","They're raising their arms.","They're lying on the floor."],"answer":2,"explanation":"정답 (C): '팔을 들어 올리고 있다.' (A)는 mat를 반복했지만 매트를 말고 있지 않다. (B)는 운동에서 연상되는 달리기이고, (D)는 사람들이 서 있으므로 틀리다.","part":1},{"id":"p1-077","level":1,"type":"사물·배경","scene":"주차 건물 안에 승용차 여러 대가 칸마다 주차되어 있다. 사람은 보이지 않는다.","statements":["Some cars are parked in a garage.","Some people are getting into a car.","A car is being washed.","A man is driving out of a garage."],"answer":0,"explanation":"정답 (A): '차들이 주차장에 세워져 있다.' 사람이 없는 사진인데 (B)와 (D)는 사람의 동작을 묘사했다. (C)는 세차 중이 아니다.","part":1},{"id":"p1-078","level":1,"type":"사물·배경","scene":"건물 뒤편에 파란색·초록색·노란색 분리수거함 세 개가 나란히 놓여 있다. 사람은 없다.","statements":["Someone is emptying a bin.","There are three bins side by side.","The bins are on a truck.","A man is carrying a bag of trash."],"answer":1,"explanation":"정답 (B): '수거함 세 개가 나란히 있다.' (A)와 (D)는 사진에 없는 사람을 등장시켰고, (C)는 수거함이 트럭 위가 아니라 바닥에 놓여 있으므로 틀리다.","part":1},{"id":"p1-079","level":1,"type":"상태(수동태 진행/완료)","scene":"꽃집 앞 인도에 꽃이 꽂힌 양동이들이 줄지어 놓여 있다. 사람은 없다.","statements":["Some flowers are being planted.","A woman is buying flowers.","The shop is closed for the day.","Some flowers have been placed outside a shop."],"answer":3,"explanation":"정답 (D): '꽃들이 가게 밖에 놓여 있다.' (A)는 flowers를 반복했지만 심는 중(being planted)이 아니고, (B)는 사람이 없는 사진이다. (C)는 사진만으로 영업 여부를 알 수 없다.","part":1},{"id":"p1-080","level":1,"type":"상태(수동태 진행/완료)","scene":"캠핑장 잔디밭에 텐트 두 개가 쳐져 있다. 주변에 사람은 없다.","statements":["Some tents are being taken down.","Some people are sleeping in a tent.","Some tents are folded in a bag.","Some tents have been set up on the grass."],"answer":3,"explanation":"정답 (D): '텐트가 잔디 위에 설치되어 있다.' (A)는 '걷는 중'이라 사람이 필요하고, (B)는 사람이 보이지 않는다. (C)는 텐트가 가방에 접혀 있지 않고 펼쳐져 있다.","part":1},{"id":"p1-081","level":2,"type":"1인 동작","scene":"농산물 직판장 가판대에서 한 남자가 저울 위에 토마토를 올려 무게를 달고 있다.","statements":["He's weighing some tomatoes.","He's planting some tomatoes.","He's cooking some vegetables.","He's paying for his groceries."],"answer":0,"explanation":"정답 (A): '토마토 무게를 달고 있다.' (B)는 tomatoes를 반복했지만 심는 동작이 아니고, (C)는 채소에서 연상되는 요리다. (D)는 시장에서 연상되는 계산 동작이지만 돈을 내고 있지 않다.","part":1},{"id":"p1-082","level":2,"type":"1인 동작","scene":"녹음실에서 헤드폰을 쓴 여자가 스탠드 마이크 앞에서 노래를 부르고 있다.","statements":["She's singing into a microphone.","She's taking off her headphones.","She's playing the piano.","She's repairing a microphone."],"answer":0,"explanation":"정답 (A): '마이크에 대고 노래하고 있다.' (B)는 헤드폰을 '쓰고 있는' 상태를 '벗는 중(taking off)'으로 바꾼 전형적 함정이다. (C)는 피아노가 없고, (D)는 microphone을 반복했지만 수리 중이 아니다.","part":1},{"id":"p1-083","level":2,"type":"1인 동작","scene":"주유소에서 한 남자가 주유기 노즐을 차에 꽂고 기름을 넣고 있다.","statements":["He's cleaning a windshield.","He's getting out of a car.","He's pumping gas into a car.","He's paying at a counter."],"answer":2,"explanation":"정답 (C): '차에 기름을 넣고 있다.' (A)는 주유소에서 연상되는 앞유리 닦기, (B)는 이미 차 밖에 서 있으므로 틀리고, (D)는 계산대가 보이지 않는다.","part":1},{"id":"p1-084","level":2,"type":"2인 이상 동작","scene":"사무실 건물 외벽에서 작업자 두 명이 곤돌라에 서서 긴 막대 걸레로 유리창을 닦고 있다.","statements":["Some workers are opening the windows.","They're climbing down a ladder.","Some workers are cleaning windows.","They're painting the building."],"answer":2,"explanation":"정답 (C): '창문을 닦고 있다.' (A)는 windows를 반복했지만 여는 동작이 아니다. (B)는 사다리가 아닌 곤돌라에 있고, (D)는 높은 곳 작업에서 연상되는 페인트칠이다.","part":1},{"id":"p1-085","level":2,"type":"2인 이상 동작","scene":"도예 교실에서 여러 사람이 각자 물레 앞에 앉아 젖은 점토로 그릇 모양을 빚고 있다.","statements":["They're washing some dishes.","They're painting a picture.","They're standing in a line.","They're shaping some clay."],"answer":3,"explanation":"정답 (D): '점토를 빚고 있다.' (A)는 그릇(dish)에서 연상되는 설거지이고, (B)는 미술 수업에서 연상되는 그림 그리기다. (C)는 모두 앉아 있으므로 틀리다.","part":1},{"id":"p1-086","level":2,"type":"2인 이상 동작","scene":"동물병원 진료대 위에 개가 올라가 있고, 수의사가 청진기로 진찰하는 동안 주인이 개를 붙잡고 있다.","statements":["A man is walking a dog in a park.","A veterinarian is examining a dog.","They're feeding the dog.","A dog is sleeping on the floor."],"answer":1,"explanation":"정답 (B): '수의사가 개를 진찰하고 있다.' (A)는 dog을 반복했지만 장소가 공원이 아니다. (C)는 먹이를 주고 있지 않고, (D)는 개가 바닥이 아니라 진료대 위에 있다.","part":1},{"id":"p1-087","level":2,"type":"사물·배경","scene":"제과점 유리 진열장 안에 케이크와 빵들이 여러 층으로 진열되어 있다. 손님은 없다.","statements":["A baker is decorating a cake.","Some bread is being sliced.","The shelves are empty.","Some pastries are on display."],"answer":3,"explanation":"정답 (D): '빵과 과자가 진열되어 있다.' (A)와 (B)는 사진에 없는 사람의 동작이 필요한 문장이다. (C)는 진열장이 가득 차 있으므로 반대 내용이다.","part":1},{"id":"p1-088","level":2,"type":"사물·배경","scene":"쇼핑몰 1층과 2층을 잇는 에스컬레이터 두 대가 나란히 있다. 아무도 타고 있지 않다.","statements":["People are riding an escalator.","There are escalators between two floors.","An escalator is being repaired.","Some shoppers are carrying bags."],"answer":1,"explanation":"정답 (B): '두 층 사이에 에스컬레이터가 있다.' (A)와 (D)는 사람이 없는데 사람을 묘사했다. (C)는 수리 중(being repaired)이라면 작업자가 보여야 한다.","part":1},{"id":"p1-089","level":2,"type":"상태(수동태 진행/완료)","scene":"건물 옥상 정원에 나무 화분들이 줄지어 놓여 있고, 화분마다 채소가 자라고 있다. 사람은 없다.","statements":["Some planters have been arranged in rows.","Some plants are being watered.","A woman is picking vegetables.","Some planters are hanging from a roof."],"answer":0,"explanation":"정답 (A): '화분들이 줄지어 배치되어 있다.' (B)는 물을 주는 중(being watered)이라 사람이 필요하고, (C)는 사람이 없다. (D)는 화분이 매달려 있지 않고 바닥에 놓여 있다.","part":1},{"id":"p1-090","level":2,"type":"상태(수동태 진행/완료)","scene":"행사 전 연회장. 둥근 테이블마다 흰 식탁보가 덮여 있고 의자가 둘러 놓여 있다. 사람은 없다.","statements":["A server is removing a tablecloth.","The tables have been covered with cloths.","Guests are seated at the tables.","The tables are being set up outside."],"answer":1,"explanation":"정답 (B): '테이블이 식탁보로 덮여 있다.' (A)와 (C)는 사진에 없는 사람을 묘사했다. (D)는 실내이고, 설치 중(being set up)인 상태도 아니다.","part":1},{"id":"p1-091","level":3,"type":"1인 동작","scene":"양복점에서 목에 줄자를 건 재단사가 마네킹에 입힌 재킷의 어깨 너비를 줄자로 재고 있다.","statements":["He's trying on a jacket.","He's sewing a button onto a shirt.","He's hanging a jacket on a rack.","He's taking a measurement."],"answer":3,"explanation":"정답 (D): '치수를 재고 있다.' (A)는 재킷을 입어 보는 사람이 아니라 마네킹이 입고 있다. (B)는 재단사에서 연상되는 바느질이고, (C)는 jacket을 반복했지만 옷걸이에 거는 동작이 아니다.","part":1},{"id":"p1-092","level":3,"type":"1인 동작","scene":"서점 입구의 진열대에서 한 여자가 신간 책들을 표지가 보이도록 세워 놓고 있다.","statements":["She's reading a book at a table.","She's paying for some books.","She's setting up a book display.","She's packing books into a box."],"answer":2,"explanation":"정답 (C): '책 진열을 하고 있다.' (A)는 책을 읽고 있지 않고, (B)는 서점에서 연상되는 계산이다. (D)는 책을 상자에서 꺼내 놓는 쪽이지 상자에 넣고 있지 않다.","part":1},{"id":"p1-093","level":3,"type":"2인 이상 동작","scene":"텅 빈 공연장 무대에서 지휘자가 지휘봉을 들고 있고, 단원들이 악보를 보며 악기를 연주하고 있다. 객석은 비어 있다.","statements":["An audience is applauding.","Some musicians are playing instruments.","The musicians are putting away their instruments.","A conductor is sitting in the front row."],"answer":1,"explanation":"정답 (B): '연주자들이 악기를 연주하고 있다.' (A)는 객석이 비어 있으므로 틀리고, (C)는 instruments를 반복했지만 악기를 정리하는 중이 아니다. (D)는 지휘자가 무대에 서 있으므로 틀리다.","part":1},{"id":"p1-094","level":3,"type":"2인 이상 동작","scene":"스키장에서 스키를 신은 두 사람이 리프트 의자에 나란히 앉아 슬로프 위쪽으로 올라가고 있다.","statements":["They're skiing down a slope.","Two people are riding a ski lift.","They're putting on their skis.","They're waiting in line for a lift."],"answer":1,"explanation":"정답 (B): '두 사람이 스키 리프트를 타고 있다.' (A)는 스키장에서 연상되는 활강 동작이고, (C)는 이미 스키를 신은 상태를 '신는 중'으로 바꾼 함정이다. (D)는 이미 리프트에 타 있으므로 틀리다.","part":1},{"id":"p1-095","level":3,"type":"사물·배경","scene":"음료 공장의 컨베이어 벨트 위로 빈 유리병들이 일렬로 이동하고 있다. 작업자는 보이지 않는다.","statements":["Some bottles are moving along a conveyor belt.","Workers are filling some bottles.","Some bottles have fallen on the floor.","A belt is being repaired."],"answer":0,"explanation":"정답 (A): '병들이 컨베이어 벨트를 따라 이동하고 있다.' (B)와 (D)는 작업자가 없는데 사람의 동작을 전제한다. (C)는 병들이 넘어져 있지 않다.","part":1},{"id":"p1-096","level":3,"type":"사물·배경","scene":"바다 위를 지나는 여객선 갑판. 난간을 따라 빈 벤치들이 놓여 있고 멀리 해안선이 보인다.","statements":["There are benches along the railing of a deck.","Passengers are leaning against a railing.","A ferry is tied up at a pier.","Some benches are being painted."],"answer":0,"explanation":"정답 (A): '갑판 난간을 따라 벤치가 있다.' (B)는 railing을 반복했지만 승객이 없다. (C)는 배가 바다 위에 있으므로 부두에 묶여 있지 않고, (D)는 칠하는 사람이 없다.","part":1},{"id":"p1-097","level":3,"type":"사물·배경","scene":"주차장 출구에 차단기가 내려와 있고, 옆에 무인 정산기가 서 있다. 차량은 없다.","statements":["A barrier has been lowered at an exit.","A car is passing through a gate.","A driver is paying a fee.","Some cars are lined up at an exit."],"answer":0,"explanation":"정답 (A): '출구에 차단기가 내려와 있다.' (B)와 (D)는 차량이 없는 사진이고, (C)는 정산기에서 연상되는 요금 지불이지만 운전자가 없다.","part":1},{"id":"p1-098","level":3,"type":"상태(수동태 진행/완료)","scene":"세탁소 안 천장 레일에 비닐 커버를 씌운 셔츠와 정장들이 줄지어 걸려 있다. 사람은 없다.","statements":["Some clothes are being folded.","A customer is picking up a suit.","Some shirts are drying on a line.","Some garments have been covered in plastic."],"answer":3,"explanation":"정답 (D): '옷들이 비닐로 씌워져 있다.' (A)는 개는 중(being folded)이 아니고 걸려 있다. (B)는 손님이 없고, (C)는 빨랫줄에서 말리는 것이 아니라 비닐에 싸인 채 레일에 걸려 있다.","part":1},{"id":"p1-099","level":3,"type":"상태(수동태 진행/완료)","scene":"해변 모래사장에 선베드들이 줄지어 놓여 있고, 그 사이의 파라솔들은 모두 접혀 있다. 사람은 없다.","statements":["Some umbrellas are being opened.","Some beach umbrellas have been closed.","People are lying on the lounge chairs.","Some chairs are being stacked."],"answer":1,"explanation":"정답 (B): '파라솔들이 접혀 있다.' (A)는 umbrellas를 반복했지만 펴는 중이 아니며, 그러려면 사람이 필요하다. (C)는 선베드가 비어 있고, (D)는 의자를 쌓는 중이 아니다.","part":1},{"id":"p1-100","level":3,"type":"상태(수동태 진행/완료)","scene":"체육관 한쪽 벽에 운동 매트들이 둥글게 말린 채 세워져 있다. 사람은 없다.","statements":["Some people are exercising on mats.","Some mats are being spread on the floor.","Some mats have been rolled up.","The mats are hanging on hooks."],"answer":2,"explanation":"정답 (C): '매트들이 말려 있다.' (A)는 사람이 없고, (B)는 바닥에 펴는 중이 아니다. (D)는 매트가 고리에 걸린 것이 아니라 벽에 세워져 있다.","part":1},{"id":"p1-101","level":4,"type":"1인 동작","scene":"작업실에서 한 여자가 재봉틀 앞에 앉아 두 손으로 천을 바늘 아래로 밀어 넣고 있다.","statements":["She's cutting fabric with scissors.","She's guiding some fabric through a sewing machine.","She's threading a needle by hand.","She's folding a piece of cloth."],"answer":1,"explanation":"정답 (B): '재봉틀로 천을 밀어 넣고 있다.' (A)는 fabric을 반복했지만 가위질을 하고 있지 않다. (C)는 needle에서 연상되는 '바늘에 실 꿰기'이고, (D)는 천을 개고 있지 않다.","part":1},{"id":"p1-102","level":4,"type":"1인 동작","scene":"도로변에서 형광 조끼를 입은 측량사가 삼각대 위에 올린 측량 장비의 렌즈를 들여다보고 있다.","statements":["He's taking a photo of a building.","He's looking through a device on a tripod.","He's directing traffic.","He's folding up a tripod."],"answer":1,"explanation":"정답 (B): '삼각대 위 장비를 들여다보고 있다.' (A)는 삼각대에서 연상되는 사진 촬영 함정이고, (C)는 형광 조끼·도로에서 연상되는 교통 정리다. (D)는 tripod를 반복했지만 접는 동작이 아니다.","part":1},{"id":"p1-103","level":4,"type":"2인 이상 동작","scene":"포도밭에서 밀짚모자를 쓴 인부 두 명이 가위로 포도송이를 잘라 각자의 바구니에 담고 있다.","statements":["They're planting some vines.","They're pouring wine into glasses.","Some workers are harvesting grapes.","They're carrying a basket between them."],"answer":2,"explanation":"정답 (C): '포도를 수확하고 있다.' (A)는 포도밭에서 연상되는 '심기', (B)는 포도에서 연상되는 와인이다. (D)는 바구니를 각자 들고 있을 뿐 둘이 함께 나르고 있지 않다.","part":1},{"id":"p1-104","level":4,"type":"2인 이상 동작","scene":"방송국 스튜디오에서 한 남자가 대형 카메라의 초점을 조정하고, 진행자는 책상에 앉아 원고를 넘기고 있다.","statements":["They're both looking into a camera.","One of the men is adjusting a camera.","They're shaking hands at a desk.","A presenter is putting on a microphone."],"answer":1,"explanation":"정답 (B): '한 사람이 카메라를 조정하고 있다.' (A)는 camera를 반복했지만 두 사람 모두 카메라를 보고 있지는 않다. (C)는 악수하고 있지 않고, (D)는 진행자가 원고를 넘기고 있지 마이크를 착용하는 중이 아니다.","part":1},{"id":"p1-105","level":4,"type":"사물·배경","scene":"건물 옥상에 태양광 패널들이 같은 각도로 여러 줄 설치되어 있다. 사람은 없다.","statements":["Some panels are being installed.","Workers are cleaning a roof.","Some panels are leaning against a wall.","Rows of solar panels cover a rooftop."],"answer":3,"explanation":"정답 (D): '태양광 패널이 줄지어 옥상을 덮고 있다.' (A)는 설치 중(being installed)이라 작업자가 있어야 하고, (B)는 사람이 없다. (C)는 panels를 반복했지만 벽에 기대어 있지 않고 옥상에 고정되어 있다.","part":1},{"id":"p1-106","level":4,"type":"사물·배경","scene":"호숫가 잔디밭에 나무 피크닉 테이블 몇 개가 흩어져 있다. 테이블 위에는 아무것도 없고 사람도 없다.","statements":["Some picnic tables are unoccupied.","Some people are having lunch outdoors.","The tables are being carried to the lake.","Food has been set out on the tables."],"answer":0,"explanation":"정답 (A): '피크닉 테이블들이 비어 있다.' (B)는 사람이 없고, (C)는 옮기는 중이 아니다. (D)는 피크닉에서 연상되는 음식이지만 테이블 위에 아무것도 없다.","part":1},{"id":"p1-107","level":4,"type":"사물·배경","scene":"계단식 강의실. 좌석들이 앞쪽 무대를 향해 층층이 배열되어 있고, 무대 뒤 스크린이 내려와 있다. 사람은 없다.","statements":["The seats in the hall face a screen.","A speaker is addressing an audience.","A screen is being rolled up.","The seats have been folded and stacked."],"answer":0,"explanation":"정답 (A): '강당 좌석이 스크린을 향해 있다.' (B)는 연사도 청중도 없고, (C)는 screen을 반복했지만 말아 올리는 중이 아니다. (D)는 좌석이 쌓여 있지 않고 고정되어 있다.","part":1},{"id":"p1-108","level":4,"type":"상태(수동태 진행/완료)","scene":"우체국 뒤편. 벽면 선반의 칸마다 소포와 봉투들이 지역별로 나뉘어 꽂혀 있다. 사람은 없다.","statements":["A clerk is weighing a package.","Packages are being loaded onto a truck.","Packages have been sorted into compartments.","Some envelopes are scattered on the floor."],"answer":2,"explanation":"정답 (C): '소포들이 칸마다 분류되어 있다.' (A)는 직원이 없고, (B)는 트럭이 없으며 싣는 중도 아니다. (D)는 봉투가 선반에 정리되어 있지 바닥에 흩어져 있지 않다.","part":1},{"id":"p1-109","level":4,"type":"상태(수동태 진행/완료)","scene":"호숫가 카약 대여소. 금속 거치대에 카약들이 여러 단으로 올려져 있다. 물가에 사람은 없다.","statements":["Some kayaks are being paddled across a lake.","Kayaks are being loaded onto a car.","Some kayaks are floating near a dock.","Some kayaks have been placed on a rack."],"answer":3,"explanation":"정답 (D): '카약들이 거치대에 놓여 있다.' (A)와 (B)는 진행 수동태로 사람이 필요한 동작이다. (C)는 카약이 물 위가 아니라 거치대 위에 있다.","part":1},{"id":"p1-110","level":4,"type":"상태(수동태 진행/완료)","scene":"공연 전 빈 무대. 마이크 스탠드 세 개와 대형 스피커들이 설치되어 있고 조명이 켜져 있다. 사람은 없다.","statements":["Some equipment has been set up on a stage.","Some musicians are tuning their instruments.","Speakers are being carried off the stage.","A performer is bowing to the audience."],"answer":0,"explanation":"정답 (A): '무대 위에 장비가 설치되어 있다.' (B)와 (D)는 무대에서 연상되는 사람의 동작이지만 사람이 없다. (C)는 speakers(스피커)를 반복했지만 옮기는 중이 아니다.","part":1},{"id":"p1-111","level":5,"type":"1인 동작","scene":"쇼핑몰 벽면에 한 여자가 붓으로 대형 벽화를 그리고 있다. 옆에는 접이식 사다리와 페인트 통들이 놓여 있다.","statements":["A woman is hanging a picture on a wall.","A woman is applying paint to a wall.","A woman is climbing a ladder.","A woman is prying open a can of paint."],"answer":1,"explanation":"정답 (B): '벽에 페인트를 칠하고 있다.' (A)는 wall을 반복했지만 그림을 거는 동작이 아니다. (C)는 사다리가 옆에 있을 뿐 올라가고 있지 않고, (D)는 페인트 통이 보이지만 여는 중이 아니다.","part":1},{"id":"p1-112","level":5,"type":"2인 이상 동작","scene":"공항 보안 검색대에서 한 여행객이 가방을 엑스레이 벨트 위에 올리고, 보안 요원이 모니터를 지켜보고 있다.","statements":["A security officer is opening a suitcase.","A traveler is placing a bag on a conveyor.","Passengers are boarding a plane.","Some bags are being unloaded from a cart."],"answer":1,"explanation":"정답 (B): '여행객이 가방을 벨트에 올리고 있다.' (A)는 보안 검색에서 연상되는 가방 개봉이지만 요원은 모니터를 보고 있다. (C)는 공항에서 연상되는 탑승이고, (D)는 bags를 반복했지만 카트가 없다.","part":1},{"id":"p1-113","level":5,"type":"2인 이상 동작","scene":"푸드 트럭 창구에서 요리사가 종이봉투를 내밀고 있고, 트럭 앞에 선 손님이 손을 뻗어 받으려 하고 있다.","statements":["Some customers are ordering from a menu at a table.","A cook is stepping out of a truck.","Some people are seated in a food court.","A customer is reaching for an order."],"answer":3,"explanation":"정답 (D): '손님이 주문한 음식을 받으려고 손을 뻗고 있다.' (A)는 order를 반복했지만 테이블에서 주문하는 장면이 아니다. (B)는 요리사가 트럭 안에 있으므로 틀리고, (C)는 앉아 있는 사람이 없다.","part":1},{"id":"p1-114","level":5,"type":"사물·배경","scene":"오래된 석조 건물들 사이로 시계탑 하나가 지붕들보다 높이 솟아 있다. 거리에는 사람이 없다.","statements":["A clock tower rises above the surrounding buildings.","A clock is being repaired.","People are gathering in a square.","Some buildings are being torn down."],"answer":0,"explanation":"정답 (A): '시계탑이 주변 건물들보다 높이 솟아 있다.' (B)는 clock을 반복했지만 수리 중이 아니며, 진행 수동태는 작업자를 전제한다. (C)는 사람이 없고, (D)는 철거 중인 건물이 없다.","part":1},{"id":"p1-115","level":5,"type":"사물·배경","scene":"호텔 객실 복도. 양쪽으로 객실 문들이 일정한 간격으로 늘어서 있고, 바닥에는 긴 카펫이 깔려 있다. 사람은 없다.","statements":["A housekeeper is pushing a cart.","Doors line both sides of a hallway.","A carpet is being vacuumed.","Some doors are being painted."],"answer":1,"explanation":"정답 (B): '복도 양쪽에 문들이 늘어서 있다.' (A)는 호텔에서 연상되는 청소 직원이지만 사람이 없다. (C)는 carpet을 반복한 진행 수동태 함정이고, (D)도 칠하는 사람이 없다.","part":1},{"id":"p1-116","level":5,"type":"사물·배경","scene":"경기가 없는 날의 야구장. 관중석의 빈 좌석들이 층층이 그라운드를 내려다보고 있다.","statements":["Rows of empty seats overlook a field.","Spectators are cheering in the stands.","The field is being mowed.","Some seats are being installed."],"answer":0,"explanation":"정답 (A): '빈 좌석 줄들이 경기장을 내려다보고 있다.' (B)는 경기장에서 연상되는 관중이지만 좌석이 비어 있다. (C)는 field를 반복한 진행 수동태로 작업자가 없고, (D)도 설치 작업이 보이지 않는다.","part":1},{"id":"p1-117","level":5,"type":"상태(수동태 진행/완료)","scene":"정돈된 호텔 객실. 침대 끝에 흰 수건들이 반듯하게 개어 쌓여 있다. 사람은 없다.","statements":["A bed is being made.","Some towels are hanging on a rack.","A housekeeper is folding towels.","Some towels have been folded on a bed."],"answer":3,"explanation":"정답 (D): '수건들이 침대 위에 개어져 있다.' (A)는 이미 정돈된 침대를 '정돈되는 중'으로 바꾼 함정이다. (B)는 수건이 걸려 있지 않고 침대 위에 있으며, (C)는 개는 사람이 없다(완료 상태 vs 진행 동작).","part":1},{"id":"p1-118","level":5,"type":"상태(수동태 진행/완료)","scene":"비가 그친 식당 테라스. 의자들이 물기가 빠지도록 테이블 가장자리에 비스듬히 기대어져 있다. 손님은 없다.","statements":["Some chairs are being stacked.","Diners are seated on a terrace.","Some chairs have been tilted against the tables.","The chairs have been placed upside down on the tables."],"answer":2,"explanation":"정답 (C): '의자들이 테이블에 기울여 기대어져 있다.' (A)는 쌓는 중이 아니고, (B)는 손님이 없다. (D)는 의자가 테이블 위에 뒤집혀 올려진 것이 아니라 가장자리에 비스듬히 기대어 있으므로 위치·모양이 다르다.","part":1},{"id":"p1-119","level":5,"type":"상태(수동태 진행/완료)","scene":"자동차 정비소. 승용차 한 대가 리프트에 들려 바닥에서 높이 올라가 있다. 정비사는 보이지 않는다.","statements":["A vehicle has been raised off the ground.","A mechanic is working under a car.","A tire is being changed.","A car is being driven into a garage."],"answer":0,"explanation":"정답 (A): '차량이 바닥에서 들어 올려져 있다.' (B)는 정비소에서 연상되는 정비사이지만 사람이 없다. (C)와 (D)는 진행 수동태로, 작업 중인 사람이 필요하다.","part":1},{"id":"p1-120","level":5,"type":"상태(수동태 진행/완료)","scene":"이사 중인 사무실. 책상 위에 모니터들이 뽁뽁이(에어캡)에 싸여 있고, 테이프로 봉한 상자들이 옆에 쌓여 있다. 사람은 없다.","statements":["Some boxes are being taped shut.","Workers are unpacking some equipment.","Some equipment has been wrapped in protective material.","Some monitors have been mounted on a wall."],"answer":2,"explanation":"정답 (C): '장비가 보호재로 싸여 있다.' (A)는 상자가 이미 봉해진 상태인데 '봉하는 중'이라 했고, (B)는 사람이 없으며 짐을 푸는 것도 아니다. (D)는 monitors를 반복했지만 벽에 걸려 있지 않고 책상 위에 있다.","part":1},{"id":"p1-121","level":1,"type":"1인 동작","scene":"사무실 카펫 위에서 한 남자가 청소기를 밀고 있다. 주변에 책상과 의자가 있다.","statements":["He's vacuuming the carpet.","He's sweeping some steps.","He's moving a sofa.","He's opening a window."],"answer":0,"explanation":"정답 (A): '그는 카펫을 청소기로 청소하고 있다.' (B)는 계단도 빗자루도 없다. (C)는 소파를 옮기는 동작이 아니다. (D)는 창문을 여는 동작이 아니다.","part":1},{"id":"p1-122","level":1,"type":"1인 동작","scene":"회의실에서 한 여성이 화이트보드에 마커로 글씨를 쓰고 있다.","statements":["She's wiping a table.","She's putting on a jacket.","She's writing on a whiteboard.","She's looking out a window."],"answer":2,"explanation":"정답 (C): '그녀는 화이트보드에 글씨를 쓰고 있다.' (A)는 탁자를 닦고 있지 않다. (B)는 재킷을 입는 동작이 아니다. (D)는 창밖을 보고 있지 않다.","part":1},{"id":"p1-123","level":1,"type":"1인 동작","scene":"공원 벤치에 앉은 남자가 몸을 숙여 운동화 끈을 묶고 있다.","statements":["He's taking off his hat.","He's tying his shoe.","He's running on a track.","He's lying on the grass."],"answer":1,"explanation":"정답 (B): '그는 신발 끈을 묶고 있다.' (A)는 모자를 벗고 있지 않다. (C)는 트랙을 달리고 있지 않고 벤치에 앉아 있다. (D)는 잔디에 누워 있지 않다.","part":1},{"id":"p1-124","level":1,"type":"2인 이상 동작","scene":"두 사람이 강변 산책로를 따라 나란히 조깅하고 있다.","statements":["They're swimming in a river.","They're sitting on the grass.","They're crossing a bridge.","They're jogging along a path."],"answer":3,"explanation":"정답 (D): '그들은 길을 따라 조깅하고 있다.' (A)는 river만 들리는 함정으로, 수영하고 있지 않다. (B)는 잔디에 앉아 있지 않다. (C)는 다리를 건너고 있지 않다.","part":1},{"id":"p1-125","level":1,"type":"2인 이상 동작","scene":"구내식당 테이블에 두 직원이 마주 앉아 점심을 먹고 있다.","statements":["They're having a meal.","They're washing some dishes.","They're ordering food at a counter.","They're cleaning a table."],"answer":0,"explanation":"정답 (A): '그들은 식사를 하고 있다.' (B)는 설거지를 하고 있지 않다. (C)는 계산대에서 주문하는 장면이 아니다. (D)는 탁자를 닦고 있지 않다.","part":1},{"id":"p1-126","level":1,"type":"2인 이상 동작","scene":"세 사람이 회의 탁자에 둘러앉아 각자 노트북 화면을 보고 있다.","statements":["They're standing near a door.","They're closing their laptops.","They're sitting at a table.","They're arranging some chairs."],"answer":2,"explanation":"정답 (C): '그들은 탁자에 앉아 있다.' (A)는 문 옆에 서 있지 않다. (B)는 노트북을 보고 있을 뿐 닫고 있지 않다. (D)는 의자를 정리하고 있지 않다.","part":1},{"id":"p1-127","level":1,"type":"사물·배경","scene":"사람이 없는 책상 위에 노트북 한 대와 머그잔 하나가 놓여 있다. 바닥은 깨끗하다.","statements":["Some papers are on the floor.","There's a laptop on the desk.","A lamp is on the floor.","A man is using a computer."],"answer":1,"explanation":"정답 (B): '책상 위에 노트북이 있다.' (A)는 바닥에 종이가 없다. (C)는 바닥에 전등이 없다. (D)는 사진에 사람이 없다.","part":1},{"id":"p1-128","level":1,"type":"사물·배경","scene":"버스 한 대가 빈 정류장 옆 도로가에 서 있다. 주변에 사람은 없다.","statements":["A bus is going through a tunnel.","Some passengers are getting off.","A car is parked in a garage.","A bus is stopped at a curb."],"answer":3,"explanation":"정답 (D): '버스가 도로 연석 옆에 서 있다.' (A)는 터널을 지나고 있지 않다. (B)는 사람이 없으므로 내리는 승객도 없다. (C)는 차고에 주차된 차가 없다.","part":1},{"id":"p1-129","level":1,"type":"사물·배경","scene":"사무실 출입문 위쪽 벽에 둥근 시계가 걸려 있다.","statements":["A clock is hanging above a doorway.","A clock is lying on a desk.","A door is being painted.","A calendar is on the wall."],"answer":0,"explanation":"정답 (A): '출입구 위에 시계가 걸려 있다.' (B)는 시계는 책상 위에 놓여 있지 않다. (C)는 페인트칠하는 사람이 없다. (D)는 벽에 있는 것은 달력이 아니라 시계다.","part":1},{"id":"p1-130","level":1,"type":"상태(수동태 진행/완료)","scene":"회의실 문이 활짝 열려 있고 안에는 아무도 없다.","statements":["The room is full of people.","A man is closing the door.","The door is locked.","The door is open."],"answer":3,"explanation":"정답 (D): '문이 열려 있다.' (A)는 방에 아무도 없다. (B)는 사람이 없으므로 문을 닫는 사람도 없다. (C)는 문은 열려 있으므로 잠겨 있지 않다.","part":1},{"id":"p1-131","level":1,"type":"상태(수동태 진행/완료)","scene":"마트 입구 옆에 쇼핑 카트 여러 대가 한 줄로 끼워져 있다.","statements":["A woman is pushing a cart.","Some shopping carts are lined up.","The carts are full of groceries.","A store is being built."],"answer":1,"explanation":"정답 (B): '쇼핑 카트들이 줄지어 있다.' (A)는 카트를 미는 사람이 없다. (C)는 카트는 비어 있다. (D)는 건물을 짓고 있지 않다.","part":1},{"id":"p1-132","level":1,"type":"상태(수동태 진행/완료)","scene":"밤에 아무도 없는 사무실의 천장 조명이 모두 켜져 있다.","statements":["Some people are working late.","The windows are broken.","A man is turning off a lamp.","The lights are on."],"answer":3,"explanation":"정답 (D): '불이 켜져 있다.' (A)는 사무실에 사람이 없다. (B)는 창문이 깨져 있지 않다. (C)는 전등을 끄는 사람이 없다.","part":1},{"id":"p1-133","level":2,"type":"1인 동작","scene":"사무실 입구에서 한 여성이 벽의 고리에 코트를 걸고 있다.","statements":["She's hanging up a coat.","She's folding a scarf.","She's buttoning a jacket.","She's locking a closet."],"answer":0,"explanation":"정답 (A): '그녀는 코트를 걸고 있다.' (B)는 스카프를 개고 있지 않다. (C)는 단추를 잠그는 동작이 아니다. (D)는 벽장을 잠그고 있지 않다.","part":1},{"id":"p1-134","level":2,"type":"1인 동작","scene":"남자가 책상에서 서류 몇 장을 모아 스테이플러로 찍고 있다.","statements":["He's shredding some documents.","He's mailing an envelope.","He's stapling some papers.","He's printing a report."],"answer":2,"explanation":"정답 (C): '그는 종이 몇 장을 스테이플러로 찍고 있다.' (A)는 documents가 들리지만 파쇄하고 있지 않다. (B)는 봉투를 부치고 있지 않다. (D)는 인쇄하는 장면이 아니다.","part":1},{"id":"p1-135","level":2,"type":"1인 동작","scene":"식당 테이블 옆에서 한 여성이 물병을 기울여 유리잔에 물을 따르고 있다.","statements":["She's washing a glass.","She's pouring water into a glass.","She's opening a refrigerator.","She's wiping a counter."],"answer":1,"explanation":"정답 (B): '그녀는 유리잔에 물을 따르고 있다.' (A)는 glass를 반복한 함정으로, 씻고 있지 않다. (C)는 냉장고를 열고 있지 않다. (D)는 조리대를 닦고 있지 않다.","part":1},{"id":"p1-136","level":2,"type":"2인 이상 동작","scene":"기차역 안내판 앞에서 두 여행객이 노선도를 함께 들여다보고 있다.","statements":["They're boarding a train.","They're buying some tickets.","They're waving to each other.","They're studying a map."],"answer":3,"explanation":"정답 (D): '그들은 지도를 살펴보고 있다.' (A)는 기차에 타고 있지 않다. (B)는 표를 사는 장면이 아니다. (C)는 서로 손을 흔들고 있지 않다.","part":1},{"id":"p1-137","level":2,"type":"2인 이상 동작","scene":"상점 계산대에서 점원이 손님에게 영수증을 건네고 있다.","statements":["A cashier is handing a receipt to a customer.","A customer is trying on a sweater.","A cashier is counting some coins.","A customer is pushing a cart."],"answer":0,"explanation":"정답 (A): '점원이 손님에게 영수증을 건네고 있다.' (B)는 스웨터를 입어 보는 사람이 없다. (C)는 동전을 세고 있지 않다. (D)는 카트를 미는 손님이 없다.","part":1},{"id":"p1-138","level":2,"type":"2인 이상 동작","scene":"야외 행사장에서 한 남자가 카메라로 나란히 선 사람들의 단체 사진을 찍고 있다.","statements":["Some people are sitting in a row.","A man is fixing a camera.","A man is taking a picture of a group.","Some people are leaving an event."],"answer":2,"explanation":"정답 (C): '남자가 단체 사진을 찍고 있다.' (A)는 사람들은 앉아 있지 않고 서 있다. (B)는 카메라를 고치고 있지 않다. (D)는 행사장을 떠나고 있지 않다.","part":1},{"id":"p1-139","level":2,"type":"사물·배경","scene":"병원 대기실 벽에 잡지 꽂이가 있고 잡지들이 꽂혀 있다. 대기실은 비어 있다.","statements":["A patient is reading a magazine.","Magazines are displayed on a rack.","The chairs are all occupied.","A receptionist is answering a call."],"answer":1,"explanation":"정답 (B): '잡지들이 꽂이에 진열되어 있다.' (A)는 잡지를 읽는 사람이 없다. (C)는 대기실이 비어 있어 의자가 차 있지 않다. (D)는 접수 직원이 보이지 않는다.","part":1},{"id":"p1-140","level":2,"type":"사물·배경","scene":"나무로 둘러싸인 넓은 주차장에 차가 두 대만 세워져 있다.","statements":["Cars are lined up at a gate.","A parking lot is being paved.","Trees are being planted.","A parking area is mostly empty."],"answer":3,"explanation":"정답 (D): '주차 구역이 대부분 비어 있다.' (A)는 입구에 줄지어 선 차들이 없다. (B)는 포장 공사를 하고 있지 않다. (C)는 나무를 심는 사람이 없다.","part":1},{"id":"p1-141","level":2,"type":"사물·배경","scene":"건물 로비 계단 바로 옆에 음료 자판기 한 대가 서 있다.","statements":["A vending machine is next to a staircase.","A man is buying a drink.","Some drinks are being delivered.","An elevator door is open."],"answer":0,"explanation":"정답 (A): '자판기가 계단 옆에 있다.' (B)는 음료를 사는 사람이 없다. (C)는 배달하는 사람이 없다. (D)는 엘리베이터 문이 보이지 않는다.","part":1},{"id":"p1-142","level":2,"type":"상태(수동태 진행/완료)","scene":"사무실 창문의 블라인드가 모두 끝까지 내려져 있다.","statements":["Someone is cleaning the windows.","The windows are wide open.","The blinds have been lowered.","Some curtains are being washed."],"answer":2,"explanation":"정답 (C): '블라인드가 내려져 있다.' (A)는 창문을 닦는 사람이 없다. (B)는 블라인드가 내려져 있어 창문이 열려 있지 않다. (D)는 커튼을 빠는 사람이 없다.","part":1},{"id":"p1-143","level":2,"type":"상태(수동태 진행/완료)","scene":"부엌 싱크대 옆 건조대에 접시들이 겹겹이 쌓여 있다.","statements":["Some plates are being washed.","Some dishes are stacked in a rack.","A cook is serving a meal.","The sink is full of water."],"answer":1,"explanation":"정답 (B): '접시들이 건조대에 쌓여 있다.' (A)는 설거지하는 사람이 없으므로 being washed는 틀리다. (C)는 음식을 내는 요리사가 없다. (D)는 싱크대에 물이 차 있지 않다.","part":1},{"id":"p1-144","level":2,"type":"상태(수동태 진행/완료)","scene":"가게 유리문에 종이 안내문 한 장이 테이프로 붙어 있다.","statements":["A woman is reading a sign.","The door is being replaced.","A store is crowded with shoppers.","A notice has been posted on a door."],"answer":3,"explanation":"정답 (D): '문에 안내문이 게시되어 있다.' (A)는 안내문을 읽는 사람이 없다. (B)는 문을 교체하는 사람이 없다. (C)는 가게 안에 손님이 붐비지 않는다.","part":1},{"id":"p1-145","level":3,"type":"1인 동작","scene":"작업장에서 한 남자가 일을 시작하기 전에 셔츠 소매를 걷어 올리고 있다.","statements":["He's rolling up his sleeves.","He's putting on some gloves.","He's buttoning his jacket.","He's hanging up a shirt."],"answer":0,"explanation":"정답 (A): '그는 소매를 걷어 올리고 있다.' (B)는 장갑을 끼는 동작이 아니다. (C)는 재킷 단추를 잠그고 있지 않다. (D)는 셔츠를 입은 상태이지 걸고 있지 않다.","part":1},{"id":"p1-146","level":3,"type":"1인 동작","scene":"식료품점에서 한 여성이 팔을 뻗어 진열대 맨 위 칸의 물건을 잡으려 하고 있다.","statements":["She's pushing a shopping cart.","She's paying at a register.","She's emptying a basket.","She's reaching for an item on a shelf."],"answer":3,"explanation":"정답 (D): '그녀는 선반의 물건을 향해 손을 뻗고 있다.' (A)는 카트를 밀고 있지 않다. (B)는 계산대에서 계산하고 있지 않다. (C)는 바구니를 비우고 있지 않다.","part":1},{"id":"p1-147","level":3,"type":"1인 동작","scene":"주택 앞 보도에서 한 남자가 갈퀴로 낙엽을 긁어모으고 있다.","statements":["He's trimming a hedge.","He's raking some leaves.","He's planting a tree.","He's sweeping a porch."],"answer":1,"explanation":"정답 (B): '그는 낙엽을 갈퀴로 모으고 있다.' (A)는 산울타리를 다듬고 있지 않다. (C)는 나무를 심고 있지 않다. (D)는 현관을 빗자루로 쓸고 있지 않고 보도에서 갈퀴질을 한다.","part":1},{"id":"p1-148","level":3,"type":"2인 이상 동작","scene":"창고 앞에 세운 트럭 짐칸에서 두 작업자가 상자를 내리고 있다.","statements":["Some workers are loading a ship.","Some boxes are being opened.","Some workers are unloading a truck.","A truck is being repaired."],"answer":2,"explanation":"정답 (C): '작업자들이 트럭에서 짐을 내리고 있다.' (A)는 배에 싣고 있지 않다. (B)는 상자를 열고 있지 않다. (D)는 트럭을 고치는 사람이 없다.","part":1},{"id":"p1-149","level":3,"type":"2인 이상 동작","scene":"강당 연단에서 한 남자가 앉아 있는 청중을 향해 이야기하고 있다.","statements":["A speaker is addressing an audience.","The audience is standing up.","Some people are leaving the hall.","A man is adjusting a microphone stand."],"answer":0,"explanation":"정답 (A): '연사가 청중에게 연설하고 있다.' (B)는 청중은 앉아 있다. (C)는 강당을 떠나는 사람이 없다. (D)는 마이크 스탠드를 조정하고 있지 않다.","part":1},{"id":"p1-150","level":3,"type":"2인 이상 동작","scene":"바닷가 산책로를 따라 여러 사람이 천천히 걷고 있다. 바다 위에는 배가 없다.","statements":["Some people are fishing from a pier.","Some people are strolling along a waterfront.","Some boats are sailing past.","Some people are swimming in the sea."],"answer":1,"explanation":"정답 (B): '사람들이 물가를 따라 거닐고 있다.' (A)는 낚시하는 사람이 없다. (C)는 바다에 배가 없다. (D)는 바다에서 수영하는 사람이 없다.","part":1},{"id":"p1-151","level":3,"type":"사물·배경","scene":"바위 해안 위에 흰 등대 하나가 서 있고 주변에 사람은 없다.","statements":["Waves are crashing over a boat.","Some tourists are climbing some rocks.","A lighthouse is being painted.","A lighthouse stands on a rocky shore."],"answer":3,"explanation":"정답 (D): '등대가 바위 해안에 서 있다.' (A)는 배가 보이지 않는다. (B)는 사람이 없다. (C)는 칠하는 사람이 없으므로 being painted는 틀리다.","part":1},{"id":"p1-152","level":3,"type":"사물·배경","scene":"강 위로 긴 다리가 놓여 있고 그 위를 차들이 지나고 있다.","statements":["A ferry is approaching a dock.","A bridge is being constructed.","A bridge spans a river.","Cars are parked along the riverbank."],"answer":2,"explanation":"정답 (C): '다리가 강을 가로지르고 있다.' (A)는 배가 보이지 않는다. (B)는 이미 완성된 다리로 공사 중이 아니다. (D)는 차들은 강가에 주차되어 있지 않고 다리를 지나고 있다.","part":1},{"id":"p1-153","level":3,"type":"사물·배경","scene":"야외 시장 좌판에 나무 상자마다 사과·감자 같은 농산물이 담겨 진열되어 있다. 손님은 없다.","statements":["Produce is displayed in crates.","A vendor is weighing some apples.","Some shoppers are paying for vegetables.","Some crates are being loaded into a van."],"answer":0,"explanation":"정답 (A): '농산물이 상자에 담겨 진열되어 있다.' (B)는 상인이 보이지 않는다. (C)는 손님이 없다. (D)는 상자를 싣는 사람이 없다.","part":1},{"id":"p1-154","level":3,"type":"상태(수동태 진행/완료)","scene":"주택 뒷마당 빨랫줄에 셔츠와 수건이 널려 있다.","statements":["Some clothes are being folded.","Some laundry has been hung out to dry.","A woman is ironing a shirt.","Some towels are stacked on a shelf."],"answer":1,"explanation":"정답 (B): '빨래가 말리려고 널려 있다.' (A)는 옷을 개는 사람이 없다. (C)는 다림질하는 사람이 없다. (D)는 수건은 선반에 쌓여 있지 않고 줄에 널려 있다.","part":1},{"id":"p1-155","level":3,"type":"상태(수동태 진행/완료)","scene":"도로 한 차선에서 작업자들이 아스팔트를 새로 깔고 있다.","statements":["A road has been closed for a parade.","Some cars are being washed.","Some trucks are parked in a garage.","A road is being repaired."],"answer":3,"explanation":"정답 (D): '도로가 보수되고 있다.' (A)는 행진은 보이지 않는다. (B)는 세차하는 장면이 아니다. (C)는 차고에 주차된 트럭이 없다.","part":1},{"id":"p1-156","level":3,"type":"상태(수동태 진행/완료)","scene":"사무실 복도에 바퀴 달린 카트가 있고 그 위에 서류철들이 쌓여 있다.","statements":["Some folders are being handed out.","A cart is being pushed down a hallway.","Some folders have been stacked on a cart.","A cabinet has been emptied."],"answer":2,"explanation":"정답 (C): '서류철들이 카트 위에 쌓여 있다.' (A)는 나눠 주는 사람이 없다. (B)는 카트를 미는 사람이 없다. (D)는 캐비닛은 보이지 않는다.","part":1},{"id":"p1-157","level":4,"type":"1인 동작","scene":"약국 진열대 앞에서 한 여성이 손에 든 약병의 라벨을 자세히 읽고 있다.","statements":["She's reading the label on a container.","She's placing some bottles in a basket.","She's opening a medicine cabinet.","She's filling a prescription."],"answer":0,"explanation":"정답 (A): '그녀는 용기의 라벨을 읽고 있다.' (B)는 병을 바구니에 넣고 있지 않다. (C)는 약장을 열고 있지 않다. (D)는 약을 조제하는 약사가 아니다.","part":1},{"id":"p1-158","level":4,"type":"1인 동작","scene":"공사 현장에서 장갑을 낀 남자가 머리에 쓴 안전모를 두 손으로 고쳐 쓰고 있다.","statements":["He's taking off his work gloves.","He's hanging a helmet on a hook.","He's climbing some scaffolding.","He's adjusting his safety helmet."],"answer":3,"explanation":"정답 (D): '그는 안전모를 고쳐 쓰고 있다.' (A)는 장갑을 낀 상태이지 벗고 있지 않다. (B)는 안전모를 걸고 있지 않다. (C)는 비계를 오르고 있지 않다.","part":1},{"id":"p1-159","level":4,"type":"1인 동작","scene":"회의실 탁자 위 프로젝터 뒤쪽에 한 여성이 케이블을 꽂고 있다.","statements":["She's pulling down a screen.","She's plugging a cord into a device.","She's dimming the lights.","She's packing up a projector."],"answer":1,"explanation":"정답 (B): '그녀는 기기에 선을 꽂고 있다.' (A)는 스크린을 내리고 있지 않다. (C)는 조명을 어둡게 하고 있지 않다. (D)는 프로젝터를 챙겨 넣고 있지 않다.","part":1},{"id":"p1-160","level":4,"type":"2인 이상 동작","scene":"차가 한 대도 없는 도로의 횡단보도를 여러 보행자가 건너고 있다.","statements":["Some vehicles are lined up at an intersection.","A police officer is directing traffic.","Pedestrians are crossing a street.","Some people are waiting at a bus stop."],"answer":2,"explanation":"정답 (C): '보행자들이 길을 건너고 있다.' (A)는 도로에 차가 없다. (B)는 교통정리하는 경찰관이 없다. (D)는 정류장에서 기다리지 않고 건너고 있다.","part":1},{"id":"p1-161","level":4,"type":"2인 이상 동작","scene":"식당 주방에서 한 요리사는 냄비를 젓고, 다른 요리사는 접시에 음식을 담고 있다.","statements":["One of the cooks is stirring a pot.","The cooks are washing some pans.","One of the cooks is cutting some bread.","The cooks are taking off their aprons."],"answer":0,"explanation":"정답 (A): '요리사 중 한 명이 냄비를 젓고 있다.' (B)는 팬을 씻는 사람이 없다. (C)는 빵을 자르는 사람이 없다. (D)는 앞치마를 벗고 있지 않다.","part":1},{"id":"p1-162","level":4,"type":"2인 이상 동작","scene":"정비소에서 정비사가 열린 보닛 아래 엔진 부분을 가리키며 손님에게 보여 주고 있다.","statements":["A customer is changing a tire.","A mechanic is closing the hood of a car.","A car is being towed away.","A mechanic is showing something to a customer."],"answer":3,"explanation":"정답 (D): '정비사가 손님에게 무언가를 보여 주고 있다.' (A)는 타이어를 가는 사람이 없다. (B)는 보닛은 열려 있고 닫는 동작이 아니다. (C)는 견인되는 차가 없다.","part":1},{"id":"p1-163","level":4,"type":"사물·배경","scene":"햇볕이 강한 오후, 산책로 옆 나무들의 그림자가 보도 위에 길게 드리워져 있다. 사람은 없다.","statements":["Some trees are being cut down.","Some trees are casting shadows on a walkway.","Leaves are being swept off a path.","People are resting in the shade."],"answer":1,"explanation":"정답 (B): '나무들이 보도 위에 그림자를 드리우고 있다. cast a shadow는 사물이 주어인 진행형으로 자주 나온다.' (A)는 나무를 베는 사람이 없다. (C)는 낙엽을 쓰는 사람이 없다. (D)는 그늘에서 쉬는 사람이 없다.","part":1},{"id":"p1-164","level":4,"type":"사물·배경","scene":"개방형 사무실에 칸막이로 나뉜 업무 공간들이 줄지어 있고 자리는 비어 있다.","statements":["Employees are gathered for a meeting.","Some partitions are being installed.","Workstations are separated by partitions.","Some computers have been boxed up."],"answer":2,"explanation":"정답 (C): '업무 공간들이 칸막이로 나뉘어 있다.' (A)는 자리가 비어 있어 모인 직원이 없다. (B)는 설치하는 사람이 없으므로 being installed는 틀리다. (D)는 컴퓨터는 상자에 담겨 있지 않다.","part":1},{"id":"p1-165","level":4,"type":"사물·배경","scene":"산속 오두막 벽 옆에 장작이 높게 쌓여 있다.","statements":["Some logs are piled next to a cabin.","A man is chopping some wood.","A fire is burning in a fireplace.","A cabin is being built in the woods."],"answer":0,"explanation":"정답 (A): '통나무들이 오두막 옆에 쌓여 있다.' (B)는 장작을 패는 사람이 없다. (C)는 벽난로의 불은 보이지 않는다. (D)는 오두막은 이미 지어져 있다.","part":1},{"id":"p1-166","level":4,"type":"상태(수동태 진행/완료)","scene":"야외 식당 마당의 기둥과 기둥 사이에 등불 줄이 걸려 있다. 손님은 아직 없다.","statements":["Some guests are being seated.","Some poles are being taken down.","The tables are crowded with diners.","Some lanterns have been strung between poles."],"answer":3,"explanation":"정답 (D): '등불들이 기둥 사이에 줄로 매달려 있다.' (A)는 손님이 없으므로 안내받는 사람도 없다. (B)는 기둥을 철거하는 사람이 없다. (C)는 식사 중인 손님이 없다.","part":1},{"id":"p1-167","level":4,"type":"상태(수동태 진행/완료)","scene":"호텔 로비 중앙에 안락의자 여러 개가 둥글게 배치되어 있고 아무도 앉아 있지 않다.","statements":["Some guests are checking in.","Some armchairs have been arranged in a circle.","Some furniture is being delivered.","A rug is being rolled up."],"answer":1,"explanation":"정답 (B): '안락의자들이 원형으로 배치되어 있다.' (A)는 체크인하는 손님이 없다. (C)는 가구를 배달하는 사람이 없다. (D)는 깔개를 마는 사람이 없다.","part":1},{"id":"p1-168","level":4,"type":"상태(수동태 진행/완료)","scene":"사무실 서류 캐비닛의 맨 위 서랍 하나가 열린 채로 있고 주변에 사람은 없다.","statements":["Some files are being sorted.","A cabinet is being moved.","A drawer has been left open.","Some keys have been left on a desk."],"answer":2,"explanation":"정답 (C): '서랍이 열린 채로 있다.' (A)는 서류를 분류하는 사람이 없다. (B)는 캐비닛을 옮기는 사람이 없다. (D)는 책상 위 열쇠는 보이지 않는다.","part":1},{"id":"p1-169","level":5,"type":"1인 동작","scene":"작업대 앞에서 한 남자가 열린 공구함 안으로 손을 넣어 무언가를 찾고 있다.","statements":["He's locking a tool chest.","He's sorting screws into bins.","He's reaching into a toolbox.","He's sharpening a blade."],"answer":2,"explanation":"정답 (C): '그는 공구함 안으로 손을 넣고 있다.' (A)는 공구함은 열려 있고 잠그는 동작이 아니다. (B)는 나사를 분류하고 있지 않다. (D)는 날을 갈고 있지 않다.","part":1},{"id":"p1-170","level":5,"type":"1인 동작","scene":"부두 난간에 한 여성이 팔을 올려 기댄 채 바다를 바라보고 있다.","statements":["She's painting a railing.","She's resting her arms on a railing.","She's boarding a ferry.","She's tying a rope to a post."],"answer":1,"explanation":"정답 (B): '그녀는 난간에 팔을 얹고 있다.' (A)는 railing을 반복한 함정으로, 페인트칠하고 있지 않다. (C)는 배에 오르고 있지 않다. (D)는 밧줄을 묶고 있지 않다.","part":1},{"id":"p1-171","level":5,"type":"1인 동작","scene":"카페 창가에서 한 남자가 한 손에 휴대폰을 들고 화면을 보면서 머그잔으로 음료를 마시고 있다.","statements":["He's pouring a beverage.","He's making a phone call.","He's wiping a window.","He's sipping from a mug."],"answer":3,"explanation":"정답 (D): '그는 머그잔으로 음료를 조금씩 마시고 있다.' (A)는 음료를 따르고 있지 않다. (B)는 휴대폰을 들고 화면을 볼 뿐 통화하고 있지 않다. (C)는 창문을 닦고 있지 않다.","part":1},{"id":"p1-172","level":5,"type":"2인 이상 동작","scene":"공사 현장에서 안전모를 쓴 작업자들이 트럭 보닛 위에 펼친 도면을 함께 살펴보고 있다.","statements":["Some workers are studying a document spread out on a vehicle.","Some workers are rolling up a blueprint.","A truck is being loaded with equipment.","Some workers are removing their helmets."],"answer":0,"explanation":"정답 (A): '작업자들이 차량 위에 펼쳐 놓은 문서를 살펴보고 있다.' (B)는 도면은 펼쳐져 있고 마는 동작이 아니다. (C)는 트럭에 장비를 싣는 사람이 없다. (D)는 안전모를 벗고 있지 않다.","part":1},{"id":"p1-173","level":5,"type":"2인 이상 동작","scene":"건물 입구에서 한 여성이 문을 잡아 주고 있고, 상자를 든 남자가 그 문을 지나 들어가고 있다.","statements":["The man is setting a box on the ground.","The woman is locking the entrance.","A woman is holding a door open.","They're carrying a box together."],"answer":2,"explanation":"정답 (C): '여성이 문을 열린 채로 잡고 있다.' (A)는 남자는 상자를 들고 들어가고 있어 내려놓고 있지 않다. (B)는 입구를 잠그고 있지 않다. (D)는 상자는 남자 혼자 들고 있다.","part":1},{"id":"p1-174","level":5,"type":"2인 이상 동작","scene":"번화가 보도에서 한 여성이 지나가는 사람들에게 전단지를 나눠 주고 있다.","statements":["Some pedestrians are posting flyers on a wall.","A woman is distributing flyers to passersby.","Some people are lining up at a booth.","A woman is collecting some forms."],"answer":1,"explanation":"정답 (B): '여성이 행인들에게 전단지를 나눠 주고 있다.' (A)는 벽에 전단지를 붙이는 사람이 없다. (C)는 부스 앞에 줄 선 사람이 없다. (D)는 서류를 걷는 것이 아니라 나눠 주고 있다.","part":1},{"id":"p1-175","level":5,"type":"사물·배경","scene":"도서관 1층에서 위층으로 이어지는 나선형 계단이 있다. 계단에 사람은 없다.","statements":["Some people are walking down a staircase.","A handrail is being installed.","Some books have been left on the steps.","A spiral staircase leads to an upper level."],"answer":3,"explanation":"정답 (D): '나선형 계단이 위층으로 이어져 있다.' (A)는 계단에 사람이 없다. (B)는 설치하는 사람이 없으므로 being installed는 틀리다. (C)는 계단에 책이 없다.","part":1},{"id":"p1-176","level":5,"type":"사물·배경","scene":"잔잔한 강물 위에 강가의 고층 건물들이 비쳐 보인다.","statements":["Some buildings are reflected in the water.","Some buildings are being demolished.","Some boats are tied to a pier.","Some people are swimming across a river."],"answer":0,"explanation":"정답 (A): '건물들이 물에 비치고 있다.' (B)는 철거 중인 건물이 없다. (C)는 부두에 묶인 배가 없다. (D)는 강을 헤엄쳐 건너는 사람이 없다.","part":1},{"id":"p1-177","level":5,"type":"사물·배경","scene":"시골 도로를 따라 나무 울타리가 길게 이어져 있고 그 너머로 들판이 펼쳐져 있다.","statements":["Some crops are being harvested.","A fence is being repaired.","A fence runs alongside a road.","Some animals are grazing in a field."],"answer":2,"explanation":"정답 (C): '울타리가 도로를 따라 이어져 있다.' (A)는 수확하는 사람이 없다. (B)는 울타리를 고치는 사람이 없다. (D)는 들판에 동물이 없다.","part":1},{"id":"p1-178","level":5,"type":"상태(수동태 진행/완료)","scene":"연회장 벽에 접은 탁자 여러 개가 세워져 기대어 있다. 방 가운데는 비어 있다.","statements":["Some tables have been set for a banquet.","Some tables have been folded and propped against a wall.","Some chairs are being unfolded.","A floor is being polished."],"answer":1,"explanation":"정답 (B): '탁자들이 접힌 채 벽에 기대어 세워져 있다.' (A)는 탁자는 접혀 있어 연회용으로 차려져 있지 않다. (C)는 의자를 펴는 사람이 없다. (D)는 바닥을 닦는 사람이 없다.","part":1},{"id":"p1-179","level":5,"type":"상태(수동태 진행/완료)","scene":"서버실 바닥 쪽에서 여러 개의 전선이 케이블 타이로 한데 묶여 있다. 사람은 없다.","statements":["A technician is cutting some wires.","Some cables are being plugged in.","Some machines have been switched off.","Some cables have been bundled together."],"answer":3,"explanation":"정답 (D): '케이블들이 한데 묶여 있다.' (A)는 기술자가 보이지 않는다. (B)는 꽂고 있는 사람이 없으므로 being plugged in은 틀리다. (C)는 기계가 꺼져 있는지 사진으로 알 수 없다.","part":1},{"id":"p1-180","level":5,"type":"상태(수동태 진행/완료)","scene":"가게 진열대 몇 칸이 텅 비어 있고 매장 안에 직원이나 손님은 없다.","statements":["Some shelves have been left empty.","Some shelves are being stocked.","Some merchandise is being unpacked.","A clerk is removing a price tag."],"answer":0,"explanation":"정답 (A): '몇몇 선반이 빈 채로 있다.' (B)는 채우는 사람이 없으므로 being stocked는 틀리다. (C)는 상품을 꺼내는 사람이 없다. (D)는 점원이 보이지 않는다.","part":1}];
